window.GLOSSARY = [
      /* ---------- 基础概念 ---------- */
      { cat: 'basic', term: 'Plaintext', zh: '明文', zhDef: '加密前的原始文字。', enDef: 'The original readable text before encryption.' , chapters: ['caesar'], game: 'freq' },
      { cat: 'basic', term: 'Ciphertext', zh: '密文', zhDef: '加密后无法直接读懂的文本。', enDef: 'The scrambled text produced by encryption.' , chapters: ['caesar'], game: 'substitution' },
      { cat: 'basic', term: 'Key', zh: '密钥', zhDef: '控制加密/解密方式的一串秘密参数。', enDef: 'A secret parameter that controls how encryption and decryption work.' , chapters: ['caesar'], game: 'caesar' },
      { cat: 'basic', term: 'Cipher', zh: '密码（算法）', zhDef: '改变字母或比特的加密算法，区别于替换整词的 code（编码表）。', enDef: 'An algorithm that scrambles letters or bits; distinct from a code, which replaces whole words.' , game: 'substitution', chapters: ['caesar','arab']  },
      { cat: 'basic', term: 'Code', zh: '编码（表）', zhDef: '用代号（如词、数字）替换整词整句的系统。', enDef: 'A system that replaces whole words or phrases with codenames or numbers.' , game: 'nihilist', chapters: ['ww1']  },
      { cat: 'basic', term: 'Cryptanalysis', zh: '密码分析', zhDef: '不靠密钥、凭密文本身破解密码的科学。', enDef: 'The science of breaking ciphers from the ciphertext alone, without the key.' , chapters: ['arab'], game: 'codebreak' },
      { cat: 'basic', term: 'Cryptography', zh: '密码学', zhDef: '研究加密与解密技术的学科。', enDef: 'The study and practice of encryption and decryption.' , chapters: ['dawn'], game: 'campaign' },
      { cat: 'basic', term: 'Steganography', zh: '隐写术', zhDef: '把秘密藏进普通载体（文字/图片）里，隐藏的是「信息存在」这一事实本身。', enDef: 'Hiding a secret inside an innocent carrier — hiding the very fact that a secret exists.', game: 'acrostic', chapters: ['bacon']},

      /* ---------- 古典密码 ---------- */
      { cat: 'classical', term: 'Caesar Cipher', zh: '凯撒密码', zhDef: '把字母表整体平移固定位数（凯撒用 3）的替换密码。', enDef: 'A substitution cipher shifting the alphabet by a fixed number (Caesar used 3).' , game: 'caesar', chapters: ['caesar']},
      { cat: 'classical', term: 'Substitution', zh: '替换密码', zhDef: '每个字母按固定规则换成另一个字母。', enDef: 'Each letter is replaced by another according to a fixed rule.' , game: 'substitution', chapters: ['caesar','arab']},
      { cat: 'classical', term: 'Transposition', zh: '换位密码', zhDef: '字母不变，只改变它们的排列顺序（如栅栏密码）。', enDef: 'The letters stay the same but are rearranged (as in the rail fence).' , game: 'railfence', chapters: ['ww1']  },
      { cat: 'classical', term: 'Rail Fence', zh: '栅栏密码', zhDef: '把明文按锯齿形写进多行，再逐行读出，是最朴素的换位密码。', enDef: 'Plaintext is written in a zigzag across rows, then read off row by row — the plainest transposition.' , game: 'railfence', chapters: ['ww1']},
      { cat: 'classical', term: 'Affine Cipher', zh: '仿射密码', zhDef: '凯撒的升级版：先乘一个数再加一个数（E=ax+b mod 26）。', enDef: 'An upgrade of Caesar: multiply by a, then add b (E = ax+b mod 26).' , game: 'affine', chapters: ['caesar']},
      { cat: 'classical', term: 'Vigenère', zh: '维吉尼亚密码', zhDef: '用密钥逐字母决定用哪张字母表，让频率分析失效的多表替换密码。', enDef: 'A polyalphabetic cipher: the key chooses a fresh alphabet per letter, defeating frequency analysis.' , game: 'vigenere', chapters: ['bacon','bletchley']},
      { cat: 'classical', term: 'Playfair', zh: 'Playfair 密码', zhDef: '5×5 方阵把字母成对加密的英军野战密码。', enDef: 'A digraph cipher on a 5×5 square, used by the British Army.' , game: 'playfair', chapters: ['ww1','midway']},
      { cat: 'classical', term: 'ADFGVX', zh: 'ADFGVX 密码', zhDef: '德军一战的终极密码：6×6 方阵替换 + 密钥列换位的双层加密。', enDef: 'Germany\'s WWI ultimate: a 6×6 Polybius substitution plus keyed columnar transposition.' , game: 'adfgvx', chapters: ['ww1']},
      { cat: 'classical', term: 'Enigma', zh: '恩尼格玛', zhDef: '德军二战转子机：转子 + 插线板，加密等于解密的奇妙对称；曾被认为不可破译，最终被波兰与英国密码学家攻破。', enDef: 'The German WWII rotor machine: rotors plus plugboard, with the eerie symmetry that encrypting equals decrypting. Once thought unbreakable, it was broken by Polish and British cryptanalysts.' , game: 'enigma', chapters: ['bletchley']},
      { cat: 'classical', term: 'Bombe', zh: '炸弹机（Bombe）', zhDef: '图灵与韦尔奇曼设计的机电筛选机，用已知明文（crib）快速排除不可能的转子设置，大幅缩短破译时间。', enDef: 'The electromechanical sieve designed by Turing and Welchman that used cribs to eliminate impossible rotor settings at speed.' , game: 'bombe', chapters: ['bletchley']},
      { cat: 'classical', term: 'Purple', zh: '紫密（Purple）', zhDef: '日本最高外交密码机：元音路与辅音路分路置换的步进开关。', enDef: 'Japan\'s top diplomatic machine: stepping switches splitting vowels and consonants into separate paths.' , game: 'purple', chapters: ['purple']},
      { cat: 'classical', term: 'JN-25', zh: 'JN-25 密码', zhDef: '日本海军密码：码本 + 每日加表双重加密，美军靠「深度」破译。', enDef: 'The Japanese Navy cipher: codebook plus daily additive; broken by US depth analysis.' , game: 'jn25', chapters: ['midway']},

      /* ---------- 破译方法 ---------- */
      { cat: 'methods', term: 'Frequency Analysis', zh: '频率分析', zhDef: '统计字母出现次数，与语言自然频率对照来破译——肯迪 850 年发明。', enDef: 'Counting letter frequencies and matching them to the language\'s norms — invented by Al-Kindi c. 850.' , game: 'freq', chapters: ['dawn','arab','venona']},
      { cat: 'methods', term: 'Crib', zh: '已知明文（Crib）', zhDef: '猜测密文中必然存在的片段（如固定称呼），当破译钩子。', enDef: 'A guessed fragment of plaintext (like a fixed greeting) used as a hook into the cipher.' , game: 'enigma', chapters: ['bletchley']},
      { cat: 'methods', term: 'Known-Plaintext Attack', zh: '已知明文攻击', zhDef: '手握明文-密文对应片段反推密钥或系统。', enDef: 'Recovering the key or system from a known plaintext-ciphertext pair.' , game: 'workshop', chapters: ['bletchley','lorenz']},
      { cat: 'methods', term: 'Depth', zh: '深度（Depth）', zhDef: '两封共享同一天加表/同一密钥的电文相减，让密钥抵消。', enDef: 'Two messages sharing the same day\'s additive or key; subtracting them cancels the key.' , game: 'jn25', chapters: ['midway']},
      { cat: 'methods', term: 'Kasiski Test', zh: 'Kasiski 检验', zhDef: '找出密文中重复片段，推断维吉尼亚密钥长度的方法。', enDef: 'Finding repeated fragments to estimate the Vigenère key length.' , game: 'codebreak', chapters: ['bacon']},
      { cat: 'methods', term: 'Brute Force', zh: '暴力破解', zhDef: '穷举所有可能的密钥，直到解出通顺明文。', enDef: 'Trying every possible key until readable plaintext emerges.' , game: 'codebreak', chapters: ['caesar','modern']},
      { cat: 'methods', term: 'Known Plaintext', zh: '已知明文', zhDef: '破译者已知的明文片段（与 crib 同义但更宽泛）。', enDef: 'A plaintext fragment the codebreaker already knows (broader than a crib).' , game: 'venona', chapters: ['venona']  },

      /* ---------- 现代密码 ---------- */
      { cat: 'modern', term: 'One-Time Pad (OTP)', zh: '一次性密码本', zhDef: '密钥与明文等长、完全随机、只用一次的密码——香农证明其绝对不可破。', enDef: 'A truly random key as long as the message, used once — Shannon proved it is unbreakable.' , chapters: ['venona'], game: 'otp-telegraph' },
      { cat: 'modern', term: 'XOR', zh: '异或', zhDef: '按位比较的运算：相同得 0、不同得 1。现代密码的原子，A⊕K⊕K=A。', enDef: 'The bitwise operation where equal bits give 0 and different bits give 1 — the atom of modern crypto: A⊕K⊕K=A.' , game: 'xor', chapters: ['lorenz','modern']},
      { cat: 'modern', term: 'Entropy', zh: '熵', zhDef: '香农对「信息量/不确定性」的数学度量。', enDef: 'Shannon\'s mathematical measure of information and uncertainty.' , chapters: ['modern'], game: 'hashlab' },
      { cat: 'modern', term: 'Perfect Secrecy', zh: '完美保密', zhDef: '密文与明文统计独立——唯一实现方式是 OTP。', enDef: 'Ciphertext statistically independent of plaintext — achievable only with the OTP.' , chapters: ['modern'], game: 'venona' },
      { cat: 'modern', term: 'Public-Key Crypto', zh: '公钥密码', zhDef: '加密与解密用不同密钥，靠数学难题（如大数分解）保证安全。', enDef: 'Different keys to encrypt and decrypt, secured by hard math problems like factoring.' , chapters: ['modern'], game: 'rsa' },
      { cat: 'modern', term: 'Block Cipher', zh: '分组密码', zhDef: '把明文切成固定大小的块，每块用同一密钥处理（AES/DES）。', enDef: 'Plaintext is cut into fixed-size blocks, each processed with the same key (AES, DES).' , game: 'maker', chapters: ['modern']},
      { cat: 'modern', term: 'HTTPS', zh: 'HTTPS', zhDef: '网页传输加密协议——你现在读这页就在用它。', enDef: 'The encrypted web protocol — you are using it to read this page.' , chapters: ['modern'], game: 'rsa' },
      { cat: 'modern', term: 'Base64', zh: 'Base64', zhDef: '把二进制数据变成可打印文本的编码，现代协议的日常编码表示。', enDef: 'Turning binary data into printable text — the everyday code of modern protocols.' , game: 'base64', chapters: ['modern']},

      /* ---------- 人物与机构 ---------- */
      { cat: 'people', term: 'Bletchley Park', zh: '布莱切利园', zhDef: '二战英国密码破译总部：破解 Enigma 与 Lorenz 的地方。', enDef: 'Britain\'s WWII codebreaking HQ, where Enigma and Lorenz were broken.' , chapters: ['bletchley'], game: 'bombe' },
      { cat: 'people', term: 'Room 40', zh: '40 号房', zhDef: '一战英国海军部密码破译室，破译齐默尔曼电报。', enDef: 'Britain\'s WWI naval codebreaking room; it broke the Zimmermann Telegram.' , chapters: ['ww1'], game: 'jn25' },
      { cat: 'people', term: 'Colossus', zh: 'Colossus（巨像计算机）', zhDef: '弗劳尔斯造的世界第一台可编程电子计算机，用于高速统计分析破译德国洛伦兹（Tunny）密码，标志着密码破译进入电子计算机时代。', enDef: 'Flowers\' world-first programmable electronic computer, built for high-speed statistical analysis that broke the German Lorenz (Tunny) cipher, ushering cryptanalysis into the electronic age.' , chapters: ['lorenz'], game: 'lorenz' },
      { cat: 'people', term: 'SIS', zh: 'SIS（陆军信号情报处）', zhDef: '美国陆军信号情报处，弗里德曼团队破解紫密的地方。', enDef: 'The US Army Signal Intelligence Service, where Friedman\'s team broke Purple.' , chapters: ['purple'], game: 'purple' },

      /* ---------- 隐写与编码 ---------- */
      { cat: 'encoding', term: 'Bacon\'s Biliteral', zh: '培根双字体', zhDef: '用两种字形的差异，把 5 位 A/B 码藏进普通散文——二进制的先声。', enDef: 'Hiding 5-bit A/B codes in ordinary prose via two typefaces — an early glimpse of binary.', game: 'bacon', chapters: ['bacon']  },
      { cat: 'encoding', term: 'Morse Code', zh: '摩斯电码', zhDef: '用点划组合编码字母，电报时代的通用语言。', enDef: 'Encoding letters as dots and dashes — the lingua franca of the telegraph age.' , game: 'morse', chapters: ['bacon','ww1','midway','purple']},
      { cat: 'encoding', term: 'Baudot Code', zh: '博多码', zhDef: '5 比特的电传码，Tunny 密文的底层字母表。', enDef: 'The 5-bit teleprinter code underlying Tunny ciphertext.' , game: 'lorenz', chapters: ['lorenz']},
      { cat: 'encoding', term: 'Polybius Square', zh: '波利比奥斯方阵', zhDef: '把字母放进方格，用行列坐标表示——ADFGVX 的底层。', enDef: 'Letters placed in a grid and addressed by row-column coordinates — the basis of ADFGVX.' , game: 'adfgvx', chapters: ['ww1']},
      { cat: 'basic', term: 'Decryption', zh: '解密', zhDef: '用密钥把密文还原成明文的过程。', enDef: 'Restoring plaintext from ciphertext using the key.' , game: 'enigma', chapters: ['bletchley']  },
      { cat: 'basic', term: 'Encryption', zh: '加密', zhDef: '用密钥把明文变成密文的过程。', enDef: 'Turning plaintext into ciphertext using the key.' , game: 'enigma', chapters: ['bletchley']  },
      { cat: 'classical', term: 'Bifid Cipher', zh: 'Bifid 密码', zhDef: '把字母换成 5×5 方格坐标再重组的分块密码。', enDef: 'Letters become grid coordinates, then get shuffled — a blocky substitution.', game: 'bifid', chapters: ['arab']  },
      { cat: 'classical', term: 'Trifid Cipher', zh: 'Trifid 密码', zhDef: '3×3×3 立体分块：替换与换位的三维合流。', enDef: 'A 3×3×3 cubic block cipher mixing substitution and transposition.', game: 'trifid', chapters: ['arab']  },
      { cat: 'classical', term: 'Hill Cipher', zh: '希尔密码', zhDef: '用密钥矩阵对字母向量做线性变换的分组密码。', enDef: 'A block cipher multiplying letter vectors by a key matrix.', game: 'hill' , chapters: ['modern']},
      { cat: 'classical', term: 'Nihilist Cipher', zh: '虚无主义者密码', zhDef: '波利比奥斯坐标 + 密钥数字逐位相加的俄罗斯古典密码。', enDef: 'A Russian classical cipher: Polybius coordinates plus key digits.' , game: 'nihilist', chapters: ['ww1']  },
      { cat: 'classical', term: 'One-Time Pad History', zh: '一次性密码本（史）', zhDef: '1917 年 Vernam 发明，用穿孔纸带做密钥流。', enDef: 'Invented by Vernam in 1917 using punched tape key streams.', game: 'venona', chapters: ['venona']  },
      { cat: 'methods', term: 'Chosen-Plaintext Attack', zh: '选择明文攻击', zhDef: '攻击者能挑选明文并拿到对应密文。', enDef: 'The attacker can choose plaintext and obtain its ciphertext.' , game: 'catapult', chapters: ['caesar']  },
      { cat: 'methods', term: 'Birthday Attack', zh: '生日攻击', zhDef: '利用生日悖论在哈希/碰撞中加速搜索。', enDef: 'Exploiting the birthday paradox to speed up collision search.' , game: 'hashlab', chapters: ['modern']  },
      { cat: 'methods', term: 'Man-in-the-Middle', zh: '中间人攻击', zhDef: '攻击者同时冒充通信双方，截听或篡改信息。', enDef: 'An attacker impersonates both parties to intercept or alter traffic.' , game: 'bb84', chapters: ['quantum']  },
      { cat: 'methods', term: 'Traffic Analysis', zh: '流量分析', zhDef: '不读内容，仅凭报文数量/方向/时机推断情报。', enDef: 'Inferring intelligence from message volume, direction and timing without reading them.' , game: 'jn25', chapters: ['midway']  },
      { cat: 'modern', term: 'Symmetric Key', zh: '对称密钥', zhDef: '加密与解密用同一把密钥（如 AES、凯撒）。', enDef: 'One key encrypts and decrypts (AES, Caesar).' , game: 'sm4', chapters: ['modern']  },
      { cat: 'modern', term: 'Asymmetric Key', zh: '非对称密钥', zhDef: '加密与解密用不同密钥（公钥/私钥）。', enDef: 'Different keys to encrypt and decrypt (public/private).' , game: 'rsa', chapters: ['modern']  },
      { cat: 'modern', term: 'Digital Signature', zh: '数字签名', zhDef: '用私钥签名的数据，公钥可验证来源与完整性。', enDef: 'Data signed with a private key, verifiable by anyone with the public key.' , game: 'rsa', chapters: ['modern']  },
      { cat: 'modern', term: 'AES', zh: 'AES 加密', zhDef: '高级加密标准：2001 年 NIST 选定的对称分组密码（Rijndael），128 位分组、128/192/256 位密钥，取代 DES，是当今应用最广的加密算法。', enDef: 'The Advanced Encryption Standard: a symmetric block cipher (Rijndael) standardized by NIST in 2001, encrypting 128-bit blocks with 128/192/256-bit keys. It replaced DES and is the de facto standard of modern encryption.' , game: 'sm4', chapters: ['modern']  },
      { cat: 'modern', term: 'RSA', zh: 'RSA 算法', zhDef: '1977 年公开密钥算法，靠大数分解难题保证安全。', enDef: 'The 1977 public-key algorithm secured by the factoring problem.', game: 'rsa', chapters: ['modern']  },
      { cat: 'encoding', term: 'Steganographic Image', zh: '图像隐写', zhDef: '把信息藏在像素的最低有效位等隐蔽处。', enDef: 'Hiding data in the least significant bits of pixels.' , game: 'bacon', chapters: ['bacon']  },
      { cat: 'encoding', term: 'Caesar Box', zh: '凯撒方阵', zhDef: '把明文按行写入方阵再按列读出（换位）。', enDef: 'Writing plaintext into a grid by rows, reading out by columns.' , game: 'caesar', chapters: ['caesar']  },
      { cat: 'modern', term: 'Data Encryption Standard (DES)', zh: '数据加密标准', zhDef: '数据加密标准。IBM 于 1970 年代设计的对称分组密码，56 位密钥、64 位分组，曾主导商用加密数十年；因密钥过短易被暴力破解，现已被 AES 取代。', enDef: 'A symmetric block cipher developed by IBM in the 1970s that became the first standardized encryption algorithm. Using a 56-bit key on 64-bit blocks, it dominated commercial encryption for decades but is now obsolete due to brute-force vulnerability.' , game: 'sm4', chapters: ['modern']  },
      { cat: 'modern', term: 'Feistel Network', zh: '费斯妥网络', zhDef: '费斯妥网络。一种分组密码结构：数据分左右两半，每轮用轮函数处理一半并与另一半异或后交换；解密只需反向执行、无需逆函数，DES 是典型代表。', enDef: 'A structure for building block ciphers in which data is split into halves and each round applies a keyed function to one half, XORs the result into the other, then swaps them. Decryption reuses the same operations in reverse order, so the round function need not be invertible; DES is the classic example.' , game: 'sm4', chapters: ['modern']  },
      { cat: 'modern', term: 'Substitution-Permutation Network (SPN)', zh: '代换-置换网络', zhDef: '代换-置换网络。现代分组密码的通用结构：多轮交替执行代换层（S 盒打乱字节）与置换层（P 层扩散比特），兼顾混淆与扩散，AES 即采用此结构。', enDef: 'The dominant modern block-cipher construction, alternating substitution layers (S-boxes) that scramble bytes with permutation layers that spread bits across the block. Repeating these rounds achieves both confusion and diffusion; AES is the canonical SPN cipher.' , game: 'sm4', chapters: ['modern']  },
      { cat: 'modern', term: 'Elliptic Curve Cryptography (ECC)', zh: '椭圆曲线密码', zhDef: '椭圆曲线密码。基于椭圆曲线离散对数难题的公钥密码体制，同等安全强度下密钥比 RSA 短得多，适合移动设备等资源受限场景。', enDef: 'A public-key cryptosystem whose security rests on the elliptic-curve discrete logarithm problem. It offers comparable security to RSA with much shorter keys, making it efficient for mobile and constrained devices.' , game: 'rsa', chapters: ['modern']  },
      { cat: 'modern', term: 'Symmetric Cryptography', zh: '对称密码', zhDef: '对称密码。加密与解密使用同一把密钥的体制，速度快、适合大量数据；但密钥须通过安全渠道事先共享，典型算法有 AES、ChaCha20。', enDef: 'A cryptosystem in which encryption and decryption use the same secret key. It is fast and suitable for bulk data, but requires the key to be shared securely beforehand; AES and ChaCha20 are typical examples.' , game: 'sm4', chapters: ['modern']  },
      { cat: 'modern', term: 'Asymmetric Cryptography', zh: '非对称密码', zhDef: '非对称密码（公钥密码）。使用一对数学相关但无法互推的密钥：公钥公开用于加密，私钥保密用于解密，解决了密钥分发难题，如 RSA、ECC。', enDef: 'A cryptosystem using a mathematically linked key pair: a public key for encryption and a private key for decryption, where one cannot feasibly be derived from the other. It solves key distribution and enables digital signatures; RSA and ECC are examples.' , game: 'rsa', chapters: ['modern']  },
      { cat: 'modern', term: 'Cryptographic Hash', zh: '密码学哈希', zhDef: '密码学哈希。满足安全性质的哈希函数：单向不可逆、难以找到碰撞、输出看似随机；区别于普通校验和，须能抵抗恶意构造，是安全协议的核心组件。', enDef: 'A hash function meeting cryptographic security properties: preimage resistance, collision resistance, and avalanche behavior. Unlike ordinary checksums, it must withstand adversarial input, making it a core component of signatures, MACs, and integrity verification.' , game: 'hashlab', chapters: ['modern']  },
      { cat: 'modern', term: 'Salt (Cryptography)', zh: '盐', zhDef: '盐。口令哈希前附加的随机数据，使相同口令产生不同哈希值，防止彩虹表攻击与跨站哈希比对，显著提升口令存储安全性。', enDef: 'Random data prepended or appended to a password before hashing so that identical passwords yield different digests. Salting defeats rainbow-table attacks and cross-site password correlation, greatly improving stored-password security.' , game: 'hashlab', chapters: ['modern']  },
      { cat: 'modern', term: 'Initialization Vector (IV)', zh: '初始化向量', zhDef: '初始化向量。分组密码在 CBC 等链式模式下使用的随机起始值；不保密但须不可预测，确保相同明文在不同加密中产生不同密文。', enDef: 'A random initial value used by block ciphers in chaining modes such as CBC. Unlike the key it need not be secret, but it must be unpredictable, ensuring that identical plaintexts encrypt to different ciphertexts each time.' , game: 'sm4', chapters: ['modern']  },
      { cat: 'modern', term: 'Block Cipher Mode (ECB/CBC/GCM)', zh: '分组密码工作模式', zhDef: '分组密码工作模式。规定如何用分组加密处理长数据：ECB 各块独立加密但泄露模式，CBC 逐块链接并需 IV，GCM 同时提供加密与认证，推荐使用。', enDef: 'Rules for encrypting data longer than one block with a block cipher. ECB encrypts blocks independently but leaks patterns; CBC chains blocks with an IV; GCM combines encryption with authentication and is the recommended modern choice.' , game: 'block-modes', chapters: ['modern']  },
      { cat: 'modern', term: 'Quantum Cryptography', zh: '量子密码', zhDef: '量子密码。利用量子力学原理（如不可克隆定理）保证安全的密码技术，典型是量子密钥分发（QKD），理论上可证明安全，但工程实现仍有挑战。', enDef: 'Cryptographic techniques built on quantum mechanics, notably quantum key distribution (QKD), which exploits properties such as the no-cloning theorem to detect eavesdropping. It offers provable security in theory, though practical deployment faces engineering challenges.' , game: 'qkd-sim', chapters: ['quantum']  },
      { cat: 'methods', term: 'Differential Cryptanalysis', zh: '差分密码分析', zhDef: '差分密码分析。分析成对明文的固定差异在加密轮间传播的规律，统计高概率差分路径以恢复密钥；对 DES 等迭代密码特别有效，推动了密码设计演进。', enDef: 'A chosen-plaintext technique that studies how fixed differences between paired plaintexts propagate through cipher rounds. High-probability differential trails leak key information; it was crucial in breaking DES variants and shaping modern cipher design.' , game: 'sm4', chapters: ['modern']  },
      { cat: 'methods', term: 'Linear Cryptanalysis', zh: '线性密码分析', zhDef: '线性密码分析。寻找明文、密文与密钥比特间的线性近似，收集大量明密文对统计偏差来逐位恢复密钥；属已知明文攻击，对 DES 十分有效。', enDef: 'A known-plaintext attack that finds linear approximations relating plaintext, ciphertext, and key bits, then accumulates statistical bias over many pairs to recover key bits one by one. It proved highly effective against DES.' , game: 'sm4', chapters: ['modern']  },
      { cat: 'methods', term: 'Rainbow Table', zh: '彩虹表', zhDef: '彩虹表。预计算并压缩存储的「明文-哈希」链集合，用于快速反查哈希得到口令；加盐或使用慢哈希可令其失效，是口令破解的经典加速手段。', enDef: 'A precomputed, compressed table of hash chains that lets an attacker invert a hash to recover a password far faster than brute force. Salting or slow key-derivation functions render rainbow tables ineffective.' , game: 'hashlab', chapters: ['modern']  },
      { cat: 'methods', term: 'Side-Channel Attack', zh: '侧信道攻击', zhDef: '侧信道攻击。不攻击算法本身，而是利用设备运行时的物理泄露（功耗、电磁辐射、运行时间、缓存行为）推断密钥，常针对智能卡等实现。', enDef: 'An attack that exploits physical leakage from a running device—power consumption, electromagnetic emission, timing, or cache behavior—to infer secret keys, rather than attacking the algorithm\'s mathematics. Smart cards and AES implementations are common targets.' , game: 'enigma', chapters: ['bletchley']  },
      { cat: 'methods', term: 'Timing Attack', zh: '计时攻击', zhDef: '计时攻击。侧信道攻击的一种：通过精确测量操作的耗时差异推断秘密数据，如依解密时间逐位猜测密钥；常数时间实现是常用防御手段。', enDef: 'A side-channel attack that infers secrets from precise differences in operation duration, for example guessing key bits from decryption time. Constant-time implementations are the standard defense.' , game: 'enigma', chapters: ['bletchley']  },
      { cat: 'methods', term: 'Chosen-Ciphertext Attack', zh: '选择密文攻击', zhDef: '选择密文攻击。攻击者可选择任意密文并获取对应解密结果，据此推断密钥或消息；现代公钥加密须在此模型下保持安全（CCA 安全）。', enDef: 'An attack model in which the adversary may choose ciphertexts and obtain their decryptions, using the oracle to deduce keys or plaintexts. Modern public-key encryption is required to remain secure in this model (CCA security).' , game: 'rsa', chapters: ['modern']  },
      { cat: 'methods', term: 'Meet-in-the-Middle Attack', zh: '中途相遇攻击', zhDef: '中途相遇攻击。把加密分前后两段，分别从两端计算中间值并比对匹配，能以远低于暴力的代价破解双重加密等结构，2DES 因此不安全。', enDef: 'A technique that splits a cipher into two halves, computes intermediate values from both ends, and matches them to recover keys far faster than brute force. It is why double encryption, such as 2DES, offers little added security.' , game: 'bombe', chapters: ['bletchley']  },
      { cat: 'protocol', term: 'Transport Layer Security (TLS)', zh: '传输层安全协议', zhDef: '传输层安全协议。互联网上最常用的加密协议，为 HTTPS、邮件等提供机密性、完整性与身份认证；通过握手协商密钥，再以对称加密传输数据。', enDef: 'The most widely used protocol for securing Internet communications, protecting HTTPS, email, and other applications with confidentiality, integrity, and authentication. A handshake negotiates keys, after which traffic is encrypted under symmetric ciphers.' , game: 'rsa', chapters: ['modern']  },
      { cat: 'protocol', term: 'Public Key Infrastructure (PKI)', zh: '公钥基础设施', zhDef: '公钥基础设施。管理公钥的完整体系：负责证书的签发、分发、验证与吊销，通过信任链让用户可靠获得并验证他人公钥，支撑 HTTPS 等应用。', enDef: 'The complete framework for managing public keys: issuing, distributing, verifying, and revoking digital certificates through a chain of trust. It lets users reliably obtain and validate others\' public keys, underpinning HTTPS and digital signatures.' , game: 'rsa', chapters: ['modern']  },
      { cat: 'protocol', term: 'Certificate Authority (CA)', zh: '证书颁发机构', zhDef: '证书颁发机构。PKI 中的可信第三方，核实申请者身份并签发数字证书，用自己的私钥担保公钥归属；浏览器内置其根证书以建立信任链。', enDef: 'A trusted third party in a PKI that verifies an applicant\'s identity and issues digital certificates, vouching for public-key ownership with its own signature. Root certificates embedded in browsers anchor the chain of trust.' , game: 'rsa', chapters: ['modern']  },
      { cat: 'protocol', term: 'Digital Envelope', zh: '数字信封', zhDef: '数字信封。混合加密的典型实现：用对称密钥加密消息（快），再用接收方公钥加密该对称密钥；接收方先解出密钥再解密，兼顾速度与安全分发。', enDef: 'A hybrid-encryption construct: the message is encrypted with a fast symmetric key, and that key is sealed with the recipient\'s public key. The recipient unwraps the key first, then decrypts, combining speed with secure key distribution.' , game: 'rsa', chapters: ['modern']  },
      { cat: 'protocol', term: 'Key Exchange', zh: '密钥交换', zhDef: '密钥交换。双方在不安全信道上安全协商共享密钥的过程，典型如 Diffie-Hellman 与 ECDH；是建立加密会话的前提，常配合证书防中间人攻击。', enDef: 'The process by which two parties agree on a shared secret key over an insecure channel, classically via Diffie-Hellman or ECDH. It precedes encrypted sessions and is usually authenticated with certificates to prevent man-in-the-middle attacks.' , game: 'dh-handshake', chapters: ['quantum']  },
      { cat: 'protocol', term: 'End-to-End Encryption', zh: '端到端加密', zhDef: '端到端加密。消息在发送端加密、仅在接收端解密，中间服务器只转发密文而无法读取内容；用于即时通讯与云存储，如 Signal 协议。', enDef: 'A property in which messages are encrypted on the sender\'s device and decrypted only on the recipient\'s, so intermediate servers relay ciphertext they cannot read. It protects messaging and cloud-storage services, as exemplified by the Signal protocol.' , game: 'rsa', chapters: ['modern']  },
      { cat: 'protocol', term: 'Zero-Knowledge Proof', zh: '零知识证明', zhDef: '零知识证明。证明者在不泄露任何秘密的前提下向验证者证明某断言为真，如证明「我知道密码」却不透露密码；用于隐私保护与区块链。', enDef: 'A cryptographic method allowing a prover to convince a verifier that a statement is true without revealing any secret information, such as proving knowledge of a password without disclosing it. It underpins privacy systems and blockchains.' , game: 'shamir', chapters: ['modern']  },
      { cat: 'protocol', term: 'Homomorphic Encryption', zh: '同态加密', zhDef: '同态加密。允许直接对密文做运算，解密结果恰等于对明文做同样运算的结果，从而可在不泄露数据的情况下完成计算；是隐私计算核心技术，但性能开销大。', enDef: 'Encryption that permits computations directly on ciphertexts, such that decrypting the result matches computing on the plaintexts. It enables processing data without exposing it—central to privacy computing—though at significant performance cost.' , game: 'shamir', chapters: ['modern']  },
      { cat: 'protocol', term: 'Post-Quantum Cryptography', zh: '后量子密码', zhDef: '后量子密码。能抵抗量子计算机攻击的密码算法，基于格、编码、多变量等数学难题；与量子密码不同，NIST 已标准化若干算法以备迁移。', enDef: 'Cryptographic algorithms designed to resist quantum-computer attacks, based on hard problems such as lattices, codes, or multivariate equations. Distinct from quantum cryptography, it is being standardized by NIST to prepare for the quantum era.' , game: 'pqc-match', chapters: ['quantum']  },
      { cat: 'protocol', term: 'Kerckhoffs\'s Principle', zh: '柯克霍夫原则', zhDef: '柯克霍夫原则。密码体制的安全性应只依赖密钥保密，而非算法保密——即使算法完全公开，只要密钥不泄露系统仍安全；是现代密码设计的基石。', enDef: 'The maxim by Auguste Kerckhoffs that a cryptosystem should remain secure even if everything about it except the key is public. Security must rest entirely on key secrecy rather than on hiding the algorithm—a cornerstone of modern design.' , game: 'substitution', chapters: ['caesar','arab']  },
      { cat: 'basic', term: 'Authentication', zh: '认证', zhDef: '认证。确认通信对方身份真实性的过程，防止冒充；常用口令、数字证书、多因素认证等手段实现，是安全通信的首要环节。', enDef: 'The process of verifying that a communicating party is who it claims to be, preventing impersonation. It is achieved through passwords, digital certificates, multi-factor methods, and cryptographic mechanisms, and is the first step of secure communication.' , game: 'rsa', chapters: ['modern']  },
      { cat: 'basic', term: 'Integrity', zh: '完整性', zhDef: '完整性。保证数据在传输或存储过程中未被篡改的性质；通常用哈希值或消息认证码（MAC）检测任何修改，是信息安全三要素之一。', enDef: 'The property that data has not been altered during transmission or storage. It is typically enforced with hash values or message authentication codes, which reveal any modification; it is one of the three pillars of information security.' , game: 'hashlab', chapters: ['modern']  },
      { cat: 'basic', term: 'Non-repudiation', zh: '不可否认性', zhDef: '不可否认性。确保发送方无法否认自己发出过某条消息或签署过某份文件；数字签名提供此性质，常用于合同、交易与审计场景。', enDef: 'The property ensuring that a sender cannot deny having sent a message or signed a document. Digital signatures provide non-repudiation, making it essential for contracts, financial transactions, and audit trails.' , game: 'rsa', chapters: ['modern']  },
      { cat: 'basic', term: 'Confusion', zh: '混淆', zhDef: '混淆。让密文与密钥的关系极其复杂，使密钥的微小变化导致密文面目全非，增加分析难度；常通过 S 盒等非线性替换实现。', enDef: 'A Shannon design principle making the relationship between ciphertext and key as complex as possible, so that even tiny key changes drastically alter the ciphertext. It is typically realized with nonlinear S-box substitutions.' , game: 'sm4', chapters: ['modern']  },
      { cat: 'basic', term: 'Diffusion', zh: '扩散', zhDef: '扩散。让明文的每一位影响密文的许多位，把明文的统计特征分散掩盖；通过置换与线性变换实现，与混淆并称密码设计两大原则。', enDef: 'A Shannon design principle spreading each plaintext bit\'s influence across many ciphertext bits, hiding statistical structure. Implemented via permutations and linear transforms, it complements confusion as one of the two pillars of secure cipher design.' , game: 'sm4', chapters: ['modern']  },
      { cat: 'classical', term: 'Two-Square Cipher', zh: '双方形密码', zhDef: '双方形密码。用两个按密钥打乱的波利比奥斯方阵，把明文字母对在两阵中交叉替换成密文对；属双字母替换密码，比单表替换更难破解。', enDef: 'A classical digraph substitution cipher using two keyed Polybius squares. Plaintext letter pairs are replaced by the letters found at the intersections of their rows and columns across the squares, making it harder to break than single-letter substitution.' , game: 'playfair', chapters: ['ww1']  },
      { cat: 'classical', term: 'Gronsfeld Cipher', zh: '格朗斯费尔德密码', zhDef: '格朗斯费尔德密码。17 世纪德国人 Gronsfeld 发明的古典密码：用数字密钥对明文字母移位，类似维吉尼亚密码但密钥只含数字，属多表替换。', enDef: 'A classical polyalphabetic cipher invented by Gronsfeld in the seventeenth century. It shifts plaintext letters by a numeric key, resembling the Vigenère cipher but using only digits as the key, and is easily broken with modern methods.' , game: 'vigenere', chapters: ['bacon']  },

      { cat: 'people', term: 'NSA', zh: '美国国家安全局', zhDef: '美国国家安全局，负责信号情报搜集、密码分析与破译的中央情报机构，冷战期间主导拦截苏联通信，是世界上最庞大、最神秘的密码机构之一。', enDef: 'The National Security Agency is the U.S. signals intelligence agency responsible for global monitoring, collection, and cryptanalysis of foreign communications. Its Cold War code-breaking work, particularly against Soviet ciphers, shaped modern electronic surveillance and cryptography policy.' , game: 'venona', chapters: ['venona']  },
      { cat: 'people', term: 'GCHQ', zh: '英国政府通信总部', zhDef: '英国政府通信总部，负责监听外国通信并进行密码分析与破译的情报机构，前身是 1919 年成立的政府密码学校（GC&CS），二战后改组为 GCHQ；它在破译德国恩尼格玛密码机中发挥过重要作用。', enDef: 'GCHQ is the United Kingdom\'s intelligence agency for signals intelligence and cryptanalysis. Descended from wartime codebreaking organizations, it intercepted foreign communications and contributed decisively to breaking the German Enigma cipher during World War II.' , game: 'rsa', chapters: ['modern']  },
      { cat: 'people', term: 'NIST', zh: '美国国家标准与技术研究院', zhDef: '美国国家标准与技术研究院，负责制定官方密码算法标准的机构，先后通过公开竞赛选定 AES 与 SHA-3，其标准被全球政府与商业系统广泛采用。', enDef: 'NIST is a U.S. federal agency that develops technology standards, including cryptography. Through open competitions it selected the AES block cipher and SHA-3 hash function; its specifications are adopted worldwide by governments and industry to secure communications.' , game: 'pqc-match', chapters: ['quantum']  },
      { cat: 'people', term: 'VENONA Project', zh: '维诺纳计划', zhDef: '美国实施、英国早期协作的秘密破译项目，针对苏联情报机构在二战期间使用的一次一密乱码本，利用乱码本重用漏洞恢复了大量苏联间谍活动情报。', enDef: 'VENONA was a secret U.S.-British project that decrypted Soviet diplomatic and espionage messages from the 1940s. Soviet reuse of one-time pads created exploitable weaknesses, letting analysts recover plaintext and expose Soviet spy networks, including atomic espionage.' , game: 'venona', chapters: ['venona']  },
      { cat: 'methods', term: 'Ciphertext-Only Attack', zh: '唯密文攻击', zhDef: '最困难的密码分析场景，攻击者只能拿到截获的密文，没有对应的明文或密钥信息，只能依靠统计特性、语言规律或算法本身的弱点来尝试破译。', enDef: 'A ciphertext-only attack is the most challenging cryptanalysis scenario, in which the attacker has access only to intercepted ciphertext, with no matching plaintext or key material. Breaking the cipher then relies on statistical properties, linguistic patterns, or structural weaknesses of the algorithm.' , game: 'substitution', chapters: ['caesar','arab']  },
      { cat: 'methods', term: 'One-Time Pad Reuse', zh: '一次一密重用', zhDef: '一次一密密钥流被重复使用时产生的严重漏洞，攻击者将两段密文异或叠加以抵消密钥，再利用语言规律恢复明文，VENONA 项目正是利用了这一缺陷。', enDef: 'One-time pad reuse occurs when the same random key stream encrypts more than one message, fatally destroying the cipher\'s perfect secrecy. An attacker can XOR the ciphertexts to cancel the key and recover plaintext through language analysis, exactly as exploited by the VENONA project.' , game: 'venona', chapters: ['venona']  },
      { cat: 'modern', term: 'Key Length', zh: '密钥长度', zhDef: '以比特为单位衡量的密钥长度，直接决定密钥空间的大小；现代密码学认为 128 位以上的密钥足以抵御穷举攻击，是评估算法安全性的核心指标。', enDef: 'Key length is the size of a cryptographic key, measured in bits, and it directly determines the size of the key space and thus resistance to brute-force attack. Modern standards treat keys of 128 bits or longer as computationally infeasible to exhaust, making key length a primary security metric.' , game: 'sm4', chapters: ['modern']  },
      { cat: 'modern', term: 'Key Space', zh: '密钥空间', zhDef: '某一加密算法所有可能密钥构成的完整集合，其大小由密钥长度决定；密钥空间越大，攻击者穷举所有密钥所需的时间就越长，算法就越安全。', enDef: 'The key space is the complete set of all possible keys that a cipher can use, and its size is determined by the key length. A larger key space forces an attacker to spend exponentially more time trying every possibility, making the cipher more resistant to brute-force attacks.' , game: 'caesar', chapters: ['caesar']  },

      { cat: 'modern', term: 'RC4', zh: 'RC4 流密码', zhDef: '1987 年 Rivest 设计的软件流密码，把短密钥「拉长」成伪随机密钥流；曾撑起 WEP、早期 TLS 与 WPA，却因密钥流重用和输出偏差频遭攻击，如今已被全面弃用。', enDef: 'A software stream cipher designed by Ron Rivest in 1987 that stretches a short key into a pseudorandom keystream. It powered WEP, early TLS and WPA, but keystream-reuse and bias attacks led to its complete deprecation.', chapters: ['lorenz','modern'] , game: 'xor' },
      { cat: 'modern', term: 'ChaCha20', zh: 'ChaCha20 流密码', zhDef: '2008 年 Bernstein 在 Salsa20 基础上改进的流密码，纯软件实现飞快、对硬件要求低；TLS 1.3 和 WireGuard 都把它列为默认加密，是当今流密码的当红明星。', enDef: 'A stream cipher designed by Daniel Bernstein in 2008 as an improved variant of his Salsa20. It is extremely fast in pure software and low-power, and is the default cipher in TLS 1.3 and WireGuard.', chapters: ['modern'] , game: 'xor' },
      { cat: 'modern', term: 'Digital Signature Algorithm (DSA)', zh: 'DSA 数字签名算法', zhDef: '1994 年 NIST 标准化的签名算法，基于离散对数难题、由 ElGamal 签名演化而来；曾是政府与金融系统的标配，如今正被更小更快的 ECDSA 与 EdDSA 取代。', enDef: 'A US federal signature standard from 1994 built on the discrete logarithm problem and derived from ElGamal signatures. Long a government and finance staple, it is giving way to faster ECDSA and EdDSA.', chapters: ['modern'] , game: 'rsa' },
      { cat: 'modern', term: 'ElGamal', zh: 'ElGamal 算法', zhDef: '1985 年 Taher ElGamal 提出：每次加密随机挑一个临时数，同一明文可生成不同密文，安全性基于离散对数难题；既能加密也能签名，启发了后来的一大批体制。', enDef: 'Proposed by Taher ElGamal in 1985: each encryption picks a fresh random value, so the same plaintext yields different ciphertexts. Based on the discrete logarithm problem, it supports both encryption and signatures.', chapters: ['modern'] , game: 'rsa' },
      { cat: 'modern', term: 'Schnorr Signature', zh: 'Schnorr 签名', zhDef: '1989 年 Claus Schnorr 提出的签名：短、快，还能把多人的签名线性合并成一把；因专利 2008 年才到期而长期被冷落，比特币 2021 年 Taproot 升级后正式采用。', enDef: 'A signature scheme by Claus Schnorr (1989) that is short, fast, and allows multiple signatures to be linearly combined into one. Blocked by patent until 2008, it was finally adopted by Bitcoin\'s 2021 Taproot upgrade.', chapters: ['modern'] , game: 'rsa' },
      { cat: 'modern', term: 'Cipher Block Chaining (CBC)', zh: 'CBC 分组模式', zhDef: '每个明文块先与上一块密文异或再加密，让重复的明文块也产出不同的密文；需要不可预测的 IV、解密必须按顺序来，曾是使用最广的分组模式。', enDef: 'A block-cipher mode that XORs each plaintext block with the previous ciphertext block before encrypting, hiding repeating patterns. It needs an unpredictable IV, processes blocks in sequence, and was the classic default.', chapters: ['modern'] , game: 'sm4' },
      { cat: 'modern', term: 'Counter Mode (CTR)', zh: 'CTR 计数器模式', zhDef: '把递增的计数器加密后与明文异或，把分组密码变成流密码；各块完全独立、可并行处理，还能任意位置直接解密，流式传输与磁盘加密都爱它。', enDef: 'A mode that encrypts an incrementing counter and XORs it with plaintext, turning a block cipher into a stream cipher. Blocks are independent and parallelizable, and any position decrypts directly.', chapters: ['modern'] , game: 'sm4' },
      { cat: 'modern', term: 'Galois/Counter Mode (GCM)', zh: 'GCM 认证加密模式', zhDef: 'CTR 加密与 Galois 域乘法认证的组合体，一次运算同时搞定机密性与完整性（AEAD）；TLS 1.2/1.3 的默认配置，现代互联网加密的标配。', enDef: 'An AEAD mode pairing CTR encryption with Galois-field multiplication for authentication, delivering confidentiality and integrity in one pass. It is the default choice in TLS 1.2 and TLS 1.3.', chapters: ['modern'] , game: 'block-modes' },
      { cat: 'modern', term: 'Message Authentication Code (MAC)', zh: '消息认证码', zhDef: '用共享密钥给消息算出的短校验标签，接收方重算比对即可发现任何篡改；它保证「消息没被动过」，但证明不了「是谁发的」。', enDef: 'A short tag computed from a message with a shared secret key; recomputing and comparing it reveals any tampering. It proves a message is unchanged, but not who sent it.', game: 'spotdiff', chapters: ['modern'] },
      { cat: 'modern', term: 'HMAC', zh: 'HMAC 消息认证码', zhDef: '1996 年基于哈希函数（如 SHA-256）构造的 MAC，安全性几乎不依赖哈希的实现细节；TLS、JWT、API 签名里到处是它的身影。', enDef: 'A 1996 MAC built on top of a hash function such as SHA-256, whose security barely depends on the hash\'s implementation details. It appears everywhere: TLS, JWT, and API signing.', game: 'spotdiff', chapters: ['modern'] },
      { cat: 'modern', term: 'Key Derivation Function (KDF)', zh: '密钥派生函数', zhDef: '把弱口令、共享秘密或随机种子加工成合格密钥的工序，比如把「密码 + 盐」拉伸成 256 位 AES 密钥；熵不够的材料想变成密钥，全靠它把关。', enDef: 'A function that turns weak material—passwords, shared secrets, random seeds—into properly sized keys, e.g. stretching a password plus salt into a 256-bit AES key. It upgrades low-entropy input into usable key material.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'modern', term: 'bcrypt', zh: 'bcrypt 口令哈希', zhDef: '1999 年基于 Blowfish 分组密码的慢速口令哈希，故意设计成「算得慢」并内置盐，把暴力破解拖到天荒地老；Unix 系系统与众多 Web 框架沿用至今。', enDef: 'A 1999 password hash built on the Blowfish cipher, deliberately slow and with built-in salting to stall brute force. It remains the default in many Unix systems and web frameworks.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'modern', term: 'Argon2', zh: 'Argon2 口令哈希', zhDef: '2015 年密码哈希竞赛冠军，靠「吃内存 + 费 CPU」双重成本拖慢破解；主要变体有抗侧信道的 Argon2i 和通用推荐的 Argon2id。', enDef: 'Winner of the 2015 Password Hashing Competition; it forces attackers to pay in memory and CPU. Argon2i resists side channels, while Argon2id—the recommended default—combines both strengths.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'modern', term: 'Pseudorandom Function (PRF)', zh: '伪随机函数', zhDef: '输入任意数据、输出看似随机结果的函数，不知道密钥的人无法把它与真随机函数区分；HMAC 是标准例子，分组密码也常被当 PRF 用。', enDef: 'A function whose outputs look random to anyone without the key, indistinguishable from a truly random function. HMAC is the classic example, and block ciphers double as PRFs.', chapters: ['modern'] , game: 'xor' },
      { cat: 'modern', term: 'Pseudorandom Generator (PRG)', zh: '伪随机生成器', zhDef: '把一小段真随机种子「拉长」成大量看似随机的比特，流密码的密钥流就是这么来的；种子若不够随机，拉出来的全是伪随机。', enDef: 'A function that stretches a short truly random seed into a long stream of random-looking bits—exactly how stream-cipher keystreams are produced. If the seed is weak, everything downstream is weak.', chapters: ['venona','modern'] , game: 'xor' },
      { cat: 'methods', term: 'CCA2', zh: '自适应选择密文攻击（CCA2）', zhDef: '最严苛的攻击模型：攻击者可以随时向解密预言机提问，还能根据上一次的解密响应调整下一次的提问（比只能预先提问的 CCA1 更强）；现代公钥加密必须在此模型下保持安全（IND-CCA2）。', enDef: 'The strictest attack model: the adversary queries a decryption oracle adaptively, choosing each ciphertext based on previous answers (stronger than the pre-query-only CCA1). Modern public-key encryption must be secure here (IND-CCA2).', chapters: ['modern'] , game: 'rsa' },
      { cat: 'methods', term: 'Distinguishing Attack', zh: '区分攻击', zhDef: '不需要恢复密钥或明文，只要能把密文和纯随机串区分开，就算「破了一半」；现代安全证明几乎都以「攻击者无法区分」作为安全性的定义。', enDef: 'An attack that merely tells ciphertext apart from pure randomness, without recovering keys or plaintext—often enough to declare a scheme broken. Modern security proofs are phrased as indistinguishability.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'methods', term: 'Constant-Time Implementation', zh: '常数时间实现', zhDef: '让代码在秘密数据面前「面不改色」：无论密钥比特是什么，耗时都完全一致，从根上堵死计时攻击；这是 AES 等密码实现的基本功。', enDef: 'Writing code whose running time never depends on secret data, so timing reveals nothing about the key. It is the standard defense against timing attacks and a basic skill for crypto implementations.', chapters: ['modern'] , game: 'sm4' },
      { cat: 'methods', term: 'Padding Oracle Attack', zh: '填充预言机攻击', zhDef: '服务器对「填充错误」和「认证失败」给出不同回应，这小小的差别就成了攻击者逐字节撬开密文的预言机；Vaudenay 2002 年把 Bleichenbacher 的思路用在 CBC 上，POODLE 等真实漏洞都是它的亲戚。', enDef: 'When a server answers padding errors and authentication failures differently, that tiny difference becomes an oracle letting an attacker decrypt byte by byte. Vaudenay applied Bleichenbacher\'s idea to CBC in 2002; real bugs like POODLE are descendants.', chapters: ['modern'] , game: 'sm4' },
      { cat: 'methods', term: 'Backdoor', zh: '后门', zhDef: '藏在算法或实现里的秘密入口（相当于藏在系统里的木马），设计者能借此绕过加密；最著名的当属 2013 年被曝的 Dual_EC_DRBG——一个被写进标准里的、带后门的伪随机数生成器。', enDef: 'A secret way to bypass a cryptosystem, hidden inside an algorithm or its implementation (the crypto equivalent of a trojan horse). The most notorious case is Dual_EC_DRBG, a standardized random generator revealed in 2013 to contain a backdoor.', chapters: ['modern'], game: 'phishhunt' },
      { cat: 'protocol', term: 'Certificate Transparency (CT)', zh: '证书透明度', zhDef: '把每一张 TLS 证书都公开记进只可追加的公共账本，谁也别想偷偷给你签一张假证书；浏览器会拒绝查不到日志记录的证书，让 CA 的滥权无所遁形。', enDef: 'A public, append-only ledger of every issued TLS certificate, so nobody can quietly mint a fake one. Browsers reject certificates missing from the logs, keeping certificate authorities honest.', chapters: ['modern'] , game: 'rsa' },
      { cat: 'protocol', term: 'Online Certificate Status Protocol (OCSP)', zh: 'OCSP 证书状态协议', zhDef: '浏览器实时向 CA 查询「这张证书吊销了吗」的协议，比下载整张吊销列表更快更省；缺点是要每次联网问、还泄露访问痕迹，如今常被 OCSP Stapling 替代。', enDef: 'A protocol for checking a certificate\'s revocation status in real time, faster and lighter than downloading a full revocation list. Its round-trip and privacy costs led to OCSP stapling.', chapters: ['modern'] , game: 'rsa' },
      { cat: 'protocol', term: 'HTTP Strict Transport Security (HSTS)', zh: 'HSTS 强制 HTTPS', zhDef: '网站通过响应头命令浏览器「以后只准用 HTTPS 访问我」，浏览器从此自动把 http 升级成 https，从源头掐断降级劫持；银行和邮箱都在靠它。', enDef: 'A response header ordering browsers to only ever contact the site over HTTPS, auto-upgrading http links and blocking downgrade attacks. Banks and email providers rely on it.', chapters: ['modern'] , game: 'rsa' },
      { cat: 'modern', term: 'Merkle Tree', zh: '默克尔树', zhDef: '把数据块的哈希两两合并、层层向上，最终汇成单一根哈希；只要根哈希不变，任何叶子的篡改都会败露，比特币用它把整块交易压缩成一个根。', enDef: 'A structure that hashes data blocks pairwise up to a single root; any tampering with a leaf is caught at the root. Bitcoin uses it to compress a whole block of transactions into one root hash.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'modern', term: 'Proof of Work (PoW)', zh: '工作量证明', zhDef: '先完成一件「算起来难、验证起来秒过」的苦力活（比如暴力搜一个满足条件的哈希），才获得记账资格；比特币把出块成本变成攻击成本，中本聪 2008 年将其应用于货币共识。', enDef: 'Requiring a costly but instantly verifiable computation—like searching for a hash with many leading zeros—before earning the right to append a block. Bitcoin (2008) turns that cost into the price of an attack.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'modern', term: 'Hash-Based Signatures', zh: '哈希签名（基于哈希的签名）', zhDef: '只用哈希函数就能造的签名：Lamport 1979 年提出，私钥是一串秘密值、公开其哈希作公钥；不依赖数论难题、天然抗量子。SLH-DSA（FIPS 205，原 SPHINCS+）已入 NIST 后量子标准。缺点：签名大、有状态版只能签有限次。', enDef: 'Signatures built from hash functions alone: Lamport\'s 1979 scheme publishes hashes of secret values as the public key; no number-theoretic assumptions, naturally quantum-resistant. SLH-DSA (FIPS 205, formerly SPHINCS+) is NIST-standardized for post-quantum use. Drawback: large signatures, and stateful variants sign only a limited number of times.', chapters: ['modern'] , game: 'pqc-match' },
      { cat: 'modern', term: 'Learning With Errors (LWE)', zh: '带错误学习问题（LWE）', zhDef: '格密码的「镇山之宝」：给你一堆混着小噪声的线性方程，恢复其中的未知解极其困难，量子计算机也拿它没辙；NIST 选中的 Kyber 等后量子算法都建立在它之上。', enDef: 'The workhorse of lattice cryptography: recovering a secret from noisy linear equations is provably hard, even for quantum computers. NIST\'s post-quantum picks like Kyber rest on it.', chapters: ['modern'] , game: 'pqc-match' },
      { cat: 'modern', term: 'Ring-LWE (RLWE)', zh: '环带错误学习（RLWE）', zhDef: 'LWE 的多项式环版本：密钥更小、运算更快，让格密码从理论变成实用；代价是安全证明依赖环结构，NIST 的后量子标准 Kyber、Dilithium 都是它的模块化近亲。', enDef: 'The polynomial-ring version of LWE, with smaller keys and faster operations that make lattice crypto practical. Its proofs lean on ring structure; NIST\'s post-quantum standards Kyber and Dilithium are modular relatives.', chapters: ['modern'] , game: 'pqc-match' },
      { cat: 'modern', term: 'Shamir\'s Secret Sharing', zh: 'Shamir 秘密共享', zhDef: '1979 年 Shamir 的巧思：把一份秘密拆成 n 份，凑齐任意 k 份才能复原、少一份都不行；数学依据是「k 个点唯一确定一条 k-1 次多项式」，密码保险库和多签系统都在用。', enDef: 'Shamir\'s 1979 scheme splits a secret into n shares such that any k of them reconstruct it while fewer reveal nothing—thanks to the fact that k points define a unique degree k-1 polynomial. Used in vaults and multi-signature systems.', game: 'shamir', chapters: ['modern'] },
    { cat: 'methods', term: 'Phishing', zh: '钓鱼攻击', zhDef: '伪装成可信发件人，诱骗用户点击恶意链接或交出凭据——加密保护的是信息，防不住主动上钩的人。', enDef: 'Masquerading as a trusted sender to trick users into clicking malicious links or surrendering credentials — crypto secures data, not gullible humans.', game: 'phishhunt', chapters: ['modern'] },
      { cat: 'modern', term: 'Ring Signature', zh: '环签名', zhDef: '一群人里有人签了名，但没人知道具体是谁：签名用「一环」公钥生成，验证者只能确认签名者确实在环内；Monero 用它实现不可追踪的交易。', enDef: 'A signature generated with a \'ring\' of public keys that proves the signer belongs to the set without revealing which one. Monero uses ring signatures to make transactions untraceable.', chapters: ['modern'] , game: 'pqc-match' },
      { cat: 'modern', term: 'SHA-3', zh: 'SHA-3 哈希', zhDef: '由 NIST 于 2015 年标准化的哈希算法，采用 Keccak 的海绵结构，与 SHA-2 内部设计完全不同，为哈希家族提供了备用选择。', enDef: 'A hash algorithm standardized by NIST in 2015, built on the Keccak sponge construction and sharing no internal design with SHA-2, giving the hash family a backup choice.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'protocol', term: 'Key Confirmation', zh: '密钥确认', zhDef: '通信双方在握手后互相证明各自算出了同一把会话密钥，防止密钥不匹配或中间人悄悄插足。', enDef: 'After a handshake, both parties prove to each other that they derived the same session key, ruling out key mismatch or a silent man-in-the-middle.', chapters: ['modern'] , game: 'bb84' },
      { cat: 'protocol', term: 'Key Rotation', zh: '密钥轮换', zhDef: '定期或按事件更换密钥，缩短单把密钥的暴露窗口，即使某把密钥泄露，损失也被限制在最短时间内。', enDef: 'Replacing keys on a schedule or after events to shrink each key\'s exposure window, so a leaked key limits the damage to the shortest period.', chapters: ['modern'] , game: 'sm4' },
      { cat: 'modern', term: 'WebCrypto', zh: 'WebCrypto', zhDef: '浏览器内置的密码学接口，让网页直接调用 AES、RSA、哈希等原语，无需第三方库就能本地加解密与签名。', enDef: 'The browser\'s built-in cryptography API, letting web pages call AES, RSA, hashing and other primitives directly, with no third-party library needed for local encryption, decryption and signing.', chapters: ['modern'] , game: 'workshop' },
      { cat: 'methods', term: 'Password Spraying', zh: '密码喷射', zhDef: '拿少数几个弱口令（如 123456）横扫成千上万个账号，靠撞大运绕过单账户锁定策略，与撞库（凭证填充）方向相反。', enDef: 'Trying a handful of weak passwords (like 123456) across thousands of accounts, dodging per-account lockout policies by playing the odds—the counterpart of credential stuffing.', chapters: ['modern'] , game: 'phishhunt' },
      { cat: 'methods', term: 'Canary Trap', zh: '金丝雀陷阱', zhDef: '给不同人发送措辞略有差异的同一份机密，谁泄露就凭版本差异揪出内鬼，是抓泄密源的经典情报手法。', enDef: 'Giving each suspect a slightly different version of the same secret, then identifying the leaker by which version surfaces—a classic intelligence technique for tracing leaks to their source.', chapters: ['bletchley'] , game: 'intel-assess' },
      { cat: 'methods', term: 'Steganalysis', zh: '隐写分析', zhDef: '识别并提取藏在普通载体里的秘密消息的学问：统计异常、位平面纹理、卡方检验——比对加粗字符或检测像素最低有效位，是隐写术的克星。', enDef: 'The science of detecting and extracting hidden messages from innocent-looking carriers—statistical anomalies, bit-plane texture, chi-square tests; spotting bold characters or pixel-low-bit anomalies—the bane of steganography.', game: 'bacon', chapters: ['bacon','modern'] },
      { cat: 'methods', term: 'Replay Attack', zh: '重放攻击', zhDef: '截获一段合法通信后原样重发，骗系统重复执行一次操作；时间戳、随机数与序列号是常见的防御手段。', enDef: 'Intercepting a legitimate transmission and resending it unchanged to trick a system into repeating an action; timestamps, nonces and sequence numbers are common defenses.', chapters: ['modern'] , game: 'bb84' },
      { cat: 'modern', term: 'Format-Preserving Encryption (FPE)', zh: '格式保留加密', zhDef: '加密后密文与明文保持相同格式（如 16 位卡号仍为 16 位数字），让旧系统无需改动字段就能存下密文。', enDef: 'Encryption in which the ciphertext keeps the same format as the plaintext (a 16-digit card number stays 16 digits), so legacy systems can store ciphertext without changing fields.', chapters: ['modern'] , game: 'sm4' },

      /* 第四期 A5：量子时代术语（+8） */
      { cat: 'modern', term: 'BB84', zh: 'BB84 协议', zhDef: '1984 年贝内特与布拉萨德提出的首个实用量子密钥分发协议：发送方随机用两组基编码光子偏振，接收方随机选基测量；基匹配的位构成共享密钥，窃听必然引入约 25% 的误码率而暴露。', enDef: 'The first practical quantum key distribution protocol, proposed by Bennett and Brassard in 1984. The sender encodes photon polarizations in two random bases and the receiver measures in randomly chosen bases; matching positions form a shared key, while any eavesdropper unavoidably injects about 25% errors and gives herself away.', game: 'bb84', chapters: ['quantum'] },
      { cat: 'modern', term: 'Quantum Key Distribution (QKD)', zh: '量子密钥分发', zhDef: '利用量子力学原理（测不准与不可克隆）在信道上协商密钥的技术：任何窃听都会扰动量子态并留下可检测的误码指纹，安全性由物理定律而非计算复杂度保证。', enDef: 'A technique that negotiates keys over a channel using quantum mechanics (uncertainty and no-cloning): any interception disturbs the quantum states and leaves detectable error fingerprints, so security rests on physical law rather than computational hardness.', chapters: ['quantum'] , game: 'qkd-sim' },
      { cat: 'methods', term: 'Shor\'s Algorithm', zh: 'Shor 算法', zhDef: '1994 年秀尔提出的量子算法，能在多项式时间内完成大数分解与离散对数——直接瓦解 RSA、Diffie-Hellman 与 ECC 的数学根基；它的存在是后量子密码迁移的全部理由。', enDef: 'Peter Shor\'s 1994 quantum algorithm factors integers and computes discrete logarithms in polynomial time — dismantling the mathematical foundations of RSA, Diffie-Hellman and ECC at a stroke; it is the entire reason for the post-quantum migration.', chapters: ['quantum'] , game: 'pqc-match' },
      { cat: 'methods', term: 'Grover\'s Algorithm', zh: 'Grover 算法', zhDef: '1996 年格罗弗提出的量子搜索算法，把无结构暴力搜索从 N 步加速到约 √N 步；对策简单——密钥长度加倍即可，因此 AES-256 在量子时代依然安全。', enDef: 'Lov Grover\'s 1996 quantum search algorithm speeds unstructured brute force from N steps to about √N. The countermeasure is simple — double the key length — which is why AES-256 remains secure in the quantum era.', chapters: ['quantum'] , game: 'pqc-match' },
      { cat: 'protocol', term: 'Lattice-based Cryptography', zh: '格密码', zhDef: '基于高维格中「最短向量」「最近向量」等难题构造的密码体制：把数千维空间中的点阵搅进噪声，至今没有给 Shor 算法留下可乘之隙，是后量子标准的主力路线。', enDef: 'Cryptosystems built on lattice problems such as finding short or close vectors in high dimensions: points scattered through thousands of dimensions with noise added, offering no purchase for Shor\'s algorithm — the mainstay route of post-quantum standards.', chapters: ['quantum'] , game: 'pqc-match' },
      { cat: 'protocol', term: 'Kyber (ML-KEM)', zh: 'Kyber（ML-KEM）', zhDef: '基于模块格上带误差学习问题（MLWE）的密钥封装机制，2024 年被 NIST 标准化为 FIPS 203（ML-KEM），用于通用加密的量子安全迁移，已被 Chrome、Signal 等试水混合部署。', enDef: 'A key-encapsulation mechanism based on the Module Learning-With-Errors problem over module lattices, standardized by NIST as FIPS 203 (ML-KEM) in 2024 for quantum-safe general encryption; already trialed in hybrid mode by Chrome, Signal and others.', chapters: ['quantum'] , game: 'pqc-match' },
      { cat: 'protocol', term: 'Dilithium (ML-DSA)', zh: 'Dilithium（ML-DSA）', zhDef: '基于格的数字签名方案，2024 年被 NIST 标准化为 FIPS 204（ML-DSA）；签名紧凑、验证高效，与 ML-KEM 并列后量子迁移的主力签名算法。', enDef: 'A lattice-based digital signature scheme standardized by NIST as FIPS 204 (ML-DSA) in 2024; compact signatures and fast verification make it the primary post-quantum signing algorithm alongside ML-KEM.', chapters: ['quantum'] , game: 'pqc-match' },
      { cat: 'protocol', term: 'Harvest Now, Decrypt Later', zh: '先截获、后解密', zhDef: '对手今天批量囤积无法破译的密文，等量子计算机成熟后再回放解读；保密期以十年计的数据（医疗、国家档案）因此现在就需要后量子保护。', enDef: 'An adversary warehouses today\'s unbreakable ciphertexts today, waiting to replay them once quantum computers mature. Data whose secrecy horizon spans decades—medical records, state archives—therefore needs post-quantum protection right now.', chapters: ['quantum'] , game: 'pqc-match' },

      /* 第四期 B3：东方密码术语（+6） */
      { cat: 'classical', term: 'Yinfu Tally Codes', zh: '阴符', zhDef: '中国早期军事符信：《六韬》载八种符节，以竹符不同长度对应「见兵」「败军」等八类军情，两半相合为验——不着一字的密码。相传创制于姜太公。', enDef: 'An early Chinese military signal: the Liu Tao records eight tally lengths, each secretly mapping to a situation such as "enemy advancing" or "defeat". Two halves must match to authenticate — a code with no words at all. Tradition credits Duke Jiang of Qi.', chapters: ['caesar'] , game: 'acrostic' },
      { cat: 'classical', term: 'Yinshu Split Letters', zh: '阴书', zhDef: '《六韬》所记拆信术：一封密信拆作三份，由三名信使分道携带，收信人合三为一才能读全——单份被截也无法泄密，是朴素的「分割+冗余」思想。', enDef: 'A split-letter scheme from the Liu Tao: one letter is cut into three parts carried by three messengers on different routes; only recombining all three reveals the message. Any single capture leaks nothing — an early split-and-redundancy design.', chapters: ['caesar'] , game: 'acrostic' },
      { cat: 'classical', term: 'Ziyan Code', zh: '字验', zhDef: '北宋《武经总要》（1044）所载军用密写法：选一首四十字的诗，以临时约定的密钥字定位其中一字，该字在诗中的位置即对应一份四十项军情清单——每次换钥字即换一套编码。', enDef: 'A Song-dynasty military cipher from the Wujing Zongyao (1044): pick a forty-character poem; a per-message key character selects one poem position, and that position maps to one of forty pre-agreed tactical reports — change the key character and the whole encoding changes.', game: 'codebreak', chapters: ['arab'] },
      { cat: 'classical', term: 'Fanqie Code', zh: '反切码', zhDef: '明代戚继光《纪效新书》所载注音密码：取两首诗词的声母与韵母表，「声×韵」交叉组合为汉字编号——与同时代欧洲的多表替换异曲同工，却源自本土音韵学。', enDef: 'A phonetic cipher in Qi Jiguang\'s Jixiao Xinshu (1560s): initials from one poem crossed with finals from another number every Chinese character — structurally akin to Europe\'s polyalphabetic idea, but grown from native phonology.', game: 'fanqie', chapters: ['bacon'] },
      { cat: 'methods', term: 'Ninja Secret Codes', zh: '忍术隐语与暗号', zhDef: '日本戦国时代的谍报秘匿术：「乱破り」指潜入敌方破其耳目；1676 年《万川集海》辑录隐语、合符、置码等传信法门——防谍与保密并重的东方实践。', enDef: 'Sengoku-era Japan\'s tradecraft: "rappa" meant infiltrating and blinding the enemy\'s scouts, while the Bansenshukai (1676) compiled argots, matching tallies and drop points for covert messaging — counter-intelligence and secrecy as one discipline.', chapters: ['bacon'] , game: 'starflag' },
      { cat: 'methods', term: 'Variant Kana Steganography', zh: '变体假名隐写', zhDef: '平安时代日本贵族女性以「女手」（变体假名）书写往来，字形因人而异、外人难识；间或以换字与略号藏意于和歌书简之中——一种长于日常文本的柔性隐写传统。', enDef: 'Heian-era court women wrote in onna-de ("women\'s hand"), variant kana whose letterforms differed by hand and were opaque to outsiders; occasional character swaps and abbreviations hid meaning inside poems and letters — a soft steganography woven into everyday writing.', chapters: ['arab'] , game: 'bacon' },

      /* 第五期：国密体系术语（+4） */
      { cat: 'modern', term: 'SM4', zh: 'SM4 分组密码', zhDef: '中国国家商用分组密码标准（GB/T 32907-2016，曾用名 SMS4）：128 位分组、128 位密钥、32 轮非平衡 Feistel 结构，S 盒与 AES 同源思路；最初为 WAPI 无线局域网安全设计，现广泛用于国内金融与政务系统。', enDef: 'China\'s commercial block cipher standard (GB/T 32907-2016, formerly SMS4): 128-bit blocks and keys, 32-round unbalanced Feistel structure with an AES-style S-box. Originally designed for the WAPI WLAN security protocol, now widely deployed in domestic finance and government systems.', game: 'sm4', chapters: ['modern'] },
      { cat: 'protocol', term: 'SM2', zh: 'SM2 公钥算法', zhDef: '中国国家商用公钥算法标准（GB/T 32918）：基于 256 位椭圆曲线的数字签名、密钥交换与公钥加密体系——角色相当于国标版的 ECDSA+ECDH。', enDef: 'China\'s commercial public-key standard (GB/T 32918): digital signature, key exchange and encryption over a 256-bit elliptic curve — the national counterpart of ECDSA plus ECDH.', chapters: ['modern'] , game: 'gm-gateway' },
      { cat: 'modern', term: 'SM3', zh: 'SM3 哈希算法', zhDef: '中国国家商用哈希标准（GB/T 32905-2016）：输出 256 位摘要，Merkle–Damgård 结构与填充方式类似 SHA-256，安全性目标同级。', enDef: 'China\'s commercial hash standard (GB/T 32905-2016): a 256-bit digest with Merkle–Damgård strength targets and padding similar to SHA-256.', chapters: ['modern'] , game: 'gm-gateway' },
      { cat: 'protocol', term: 'ZUC (Zu Chongzhi)', zh: '祖冲之算法（ZUC）', zhDef: '以南北朝数学家祖冲之命名的序列密码：2011 年入选 3GPP LTE 安全机制成为国际标准，用于 4G/5G 通信加密——中国密码算法首次进入国际移动通信标准体系。', enDef: 'A stream cipher named after the ancient mathematician Zu Chongzhi: adopted into 3GPP LTE security in 2011 as an international standard for 4G/5G traffic — the first Chinese algorithm in global mobile security.', chapters: ['modern'] , game: 'xor' },

      /* 第五期：哈希碰撞术语（+3） */
      { cat: 'modern', term: 'MD5', zh: 'MD5 哈希', zhDef: '1991 年 Rivest 设计的 128 位哈希函数，曾是最广泛使用的文件校验与口令摘要算法；2004 年被王小云团队证实可在数小时内构造碰撞，现仅可用于非安全场景。', enDef: 'A 128-bit hash by Ron Rivest (1991), once the default for file checksums and password digests. In 2004 Xiaoyun Wang\'s team showed collisions computable in hours; today MD5 is fit only for non-security uses.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'modern', term: 'SHA-1', zh: 'SHA-1 哈希', zhDef: 'NSA 设计、160 位输出的哈希标准，长期支撑代码签名与 TLS 证书；2005 年王小云团队给出理论碰撞攻击，2017 年 Google 与 CWI 以 SHAttered 实际演示——此后浏览器与证书机构全面弃用。', enDef: 'An NSA-designed 160-bit hash standard that long underpinned code signing and TLS certificates. Theoretical collisions came from Xiaoyun Wang\'s team in 2005; in 2017 Google and CWI demonstrated SHAttered, and browsers and CAs dropped it for good.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'methods', term: 'Hash Collision Attack', zh: '哈希碰撞攻击', zhDef: '寻找两个不同输入产生相同哈希输出的攻击：对 n 位哈希，生日悖论使随机碰撞约需 2^(n/2) 次尝试；碰撞直接瓦解数字签名的「唯一性」——签名一份文件等于签名其碰撞副本。', enDef: 'Finding two different inputs with the same hash output: by the birthday bound, random collisions on an n-bit hash cost about 2^(n/2) tries. A collision breaks signature uniqueness — signing one file signs it.', chapters: ['modern'] , game: 'hashlab' },
      /* 第十二期：覆盖缺口补全25 条 */
      { cat: 'modern', term: '3DES (Triple DES)', zh: '三重 DES', zhDef: '对同一数据用 DES 加密三次（E-D-E），有效密钥 112 位。DES 到 AES 的过渡桥梁，2023 年 NIST 正式废弃。', enDef: 'DES applied three times (E-D-E) with an effective 112-bit key. The bridge from DES to AES, deprecated by NIST in 2023.', chapters: ['modern'] , game: 'sm4' },
      { cat: 'methods', term: 'Meet-in-the-Middle', zh: '中间相遇攻击', zhDef: '从明文正向加密、从密文逆向解密，在中间比对——将暴力穷举从 2^n 降至 2^(n/2)。3DES 用两次加密仍不够安全的原因。', enDef: 'Encrypt forward from plaintext and decrypt backward from ciphertext, meeting in the middle — reduces brute force from 2^n to 2^(n/2). Why double encryption is never enough.', chapters: ['modern'] , game: 'bombe' },
      { cat: 'basic', term: 'One-Way Function', zh: '单向函数', zhDef: '正向计算容易、逆向计算计算上不可行的函数。公钥密码的存在前提——如果单向函数不存在，整个公钥体系崩塌。', enDef: 'A function easy to compute forward but infeasible to invert. The existence assumption underlying ALL public-key crypto.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'basic', term: 'Trapdoor Function', zh: '陷门函数', zhDef: '一类特殊的单向函数：不知道「陷门信息」时逆向不可行，知道后逆向变容易。RSA 的陷门是素数分解知识。', enDef: 'A one-way function with a secret "trapdoor" that makes inversion easy when known. RSA\'s trapdoor is the factorization.', chapters: ['modern'] , game: 'rsa' },
      { cat: 'modern', term: 'Poly1305', zh: 'Poly1305 认证码', zhDef: '与 ChaCha20 配对的一次性消息认证码，速度快且常数时间。ChaCha20-Poly1305 是 TLS 1.3 的主力 AEAD 套件。', enDef: 'A fast one-time authenticator paired with ChaCha20. ChaCha20-Poly1305 is TLS 1.3\'s primary AEAD suite.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'protocol', term: 'Double Ratchet', zh: '双棘轮算法', zhDef: 'Signal 协议的核心：每条消息都推进一次加密棘轮，实现前向保密与自愈（被攻破后自动恢复安全）。', enDef: 'The core of the Signal Protocol: each message advances a cryptographic ratchet, providing forward secrecy and self-healing after compromise.', chapters: ['modern'] , game: 'bb84' },
      { cat: 'protocol', term: 'Kerberos', zh: 'Kerberos 认证协议', zhDef: 'MIT 开发的网络认证协议：通过可信第三方（KDC）签发票据，避免明文传密码——企业内部认证的事实标准。', enDef: 'MIT\'s network authentication protocol: a trusted third party (KDC) issues tickets, avoiding plaintext passwords — the de facto enterprise auth standard.', chapters: ['modern'] , game: 'sm4' },
      { cat: 'basic', term: 'Discrete Logarithm', zh: '离散对数', zhDef: '已知 g 和 g^x mod p，求 x——DH/ECC/ElGamal 的共同数学难题。量子计算机上的 Shor 算法可以高效求解。', enDef: 'Given g and g^x mod p, find x — the shared hard problem behind DH, ECC and ElGamal. Shor\'s algorithm solves it on quantum computers.', chapters: ['modern'] , game: 'rsa' },
      { cat: 'theoretical', term: 'Random Oracle Model', zh: '随机预言机模型', zhDef: '理想化模型：把哈希函数当作真正的随机函数来证明安全性。实际哈希不是随机预言机——但该模型下的证明仍有很强的指示意义。', enDef: 'An idealized model treating hash functions as truly random functions for security proofs. Real hashes aren\'t random oracles, but proofs in this model are strong indicators.', chapters: ['modern'] , game: 'hashlab' },
      { cat: 'protocol', term: 'Forward Secrecy', zh: '前向保密', zhDef: '会话密钥由临时参数实时生成、会话结束即销毁——即使长期私钥日后泄露，过去的通信记录也无法解密。TLS 1.3 强制开启。', enDef: 'Session keys are ephemeral and destroyed after use — even if the long-term key is later compromised, past sessions stay secure. Mandatory in TLS 1.3.', chapters: ['modern'] , game: 'bb84' },
      { cat: 'methods', term: 'Miller-Rabin', zh: 'Miller-Rabin 素性测试', zhDef: '概率性素数测试：对随机底数检验费马小定理的强化版。误判率可控制在任意低（如 2^-128），是 RSA/SM4 密钥生成的标准步骤。', enDef: 'A probabilistic primality test with arbitrarily low error rate (e.g. 2^-128). The standard step in RSA/SM4 key generation.', chapters: ['modern'] , game: 'rsa' },
      { cat: 'basic', term: 'Chinese Remainder Theorem', zh: '中国剩余定理', zhDef: '源自《孙子算经》的经典定理：已知数对若干互素模数的余数，可唯一确定该数。RSA 解密用它加速 4 倍。', enDef: 'From the ancient Chinese Sunzi Suanjing: residues modulo pairwise-coprime moduli uniquely determine a number. Speeds up RSA decryption 4×.', chapters: ['modern'] , game: 'rsa' },
      { cat: 'modern', term: 'Blowfish / Twofish', zh: 'Blowfish 与 Twofish', zhDef: 'Bruce Schneier 设计的两代分组密码：Blowfish（1993）快速免费，Twofish（1998）AES 决赛入围。均未被攻破但未成为标准。', enDef: 'Bruce Schneier\'s two block ciphers: Blowfish (1993) fast and free, Twofish (1998) an AES finalist. Neither broken, neither standard.', chapters: ['modern'] , game: 'sm4' },
      { cat: 'modern', term: 'Camellia', zh: 'Camellia', zhDef: '日本三菱与 NTT 联合设计的 128 位分组密码，2005 年入选 ISO/IEC 标准，安全性等同 AES。', enDef: 'A 128-bit block cipher by Mitsubishi and NTT, standardized as ISO/IEC 18033-3 in 2005. Security equivalent to AES.', chapters: ['modern'] , game: 'sm4' },
      { cat: 'postquantum', term: 'McEliece', zh: 'McEliece 密码', zhDef: 'Robert McEliece 1978 年提出的基于纠错码的公钥密码——50 年未被攻破，但公钥巨大。NIST 后量子候选。', enDef: 'Robert McEliece\'s 1978 code-based public-key crypto — unbroken for 50 years but with huge keys. A NIST post-quantum candidate.', chapters: ['modern'] , game: 'pqc-match' },
      { cat: 'postquantum', term: 'Falcon', zh: 'Falcon 签名', zhDef: '基于格的紧凑后量子签名算法，NIST 后量子签名候选——签名比 Dilithium 小但实现更复杂（需浮点运算）。', enDef: 'A compact lattice-based post-quantum signature, a NIST candidate — smaller signatures than Dilithium but harder to implement (floating-point).', chapters: ['quantum'] , game: 'pqc-match' },
      { cat: 'methods', term: 'Power Analysis', zh: '功耗分析', zhDef: '通过测量芯片加密时的功耗波动来推测密钥的侧信道攻击——简单功耗分析(SPA)直接读波形，差分功耗分析(DPA)用统计提取。', enDef: 'Side-channel attacks measuring chip power fluctuations during encryption to deduce keys — SPA reads waveforms directly, DPA uses statistics.', chapters: ['modern'] , game: 'enigma' },
      { cat: 'protocol', term: 'Needham-Schroeder', zh: 'Needham-Schroeder 协议', zhDef: '1978 年提出的认证协议，是 Kerberos 的理论基础——但原始版本因缺少旧密钥标识而被攻破（Lowe 1995 修正）。', enDef: 'A 1978 authentication protocol, the theoretical basis for Kerberos — the original was broken (Lowe 1995) due to a missing key-identity field.', chapters: ['modern'] , game: 'sm4' },
      { cat: 'theoretical', term: 'Bilinear Pairing', zh: '双线性配对', zhDef: '椭圆曲线上的特殊映射 e(P,Q)，满足 e(aP,bQ)=e(P,Q)^(ab)——基于配对的密码学（BLS 签名等）的数学基础。', enDef: 'A special elliptic-curve map e(P,Q) satisfying e(aP,bQ)=e(P,Q)^(ab) — the mathematical basis of pairing-based crypto (BLS signatures).', chapters: ['modern'] , game: 'rsa' },
      { cat: 'theoretical', term: 'Oblivious Transfer', zh: '不经意传输', zhDef: '发送方发出多条消息，接收方只能读取其中一条且发送方不知其选了哪条——MPC 的基础原语（Rabin 1981）。', enDef: 'Sender offers multiple messages; receiver reads exactly one, sender never knows which. The foundational primitive of MPC (Rabin 1981).', chapters: ['modern'] , game: 'millionaire' },
   
          { cat: 'classical', term: 'Scytale', zh: '斯巴达密码棒', zhDef: '公元前 5 世纪斯巴达的换位工具：羊皮纸条绕在特定粗细的木棒上书写，解下来即成乱码，只有同粗细木棒能复原。最早的军用换位密码实物。', enDef: 'A fifth-century-BCE Spartan transposition tool: a strip wound around a rod of fixed diameter is written on, and reads as gibberish unwound. Only an identical rod restores it — the earliest physical military cipher.', game: 'campaign', chapters: ['dawn'] },
      { cat: 'classical', term: 'Alberti Cipher Disk', zh: '阿尔贝蒂密码盘', zhDef: '1467 年阿尔贝蒂发明的两个同轴圆盘：转动外盘即可让每个字母使用不同替换表——多表替换的第一件实物工具。', enDef: 'Alberti\'s 1467 pair of coaxial disks: rotating the outer ring gives each letter its own substitution alphabet — the first physical polyalphabetic device.', game: 'vigenere', chapters: ['bacon'] },
      { cat: 'methods', term: 'Cardan Grille', zh: '卡当格栅', zhDef: '一张挖孔卡片：透过孔洞写密文、移开后补足无害文字。收信人用同样的格栅读出隐藏信息——文艺复兴至今仍在使用的隐写骨架。', enDef: 'A card with holes cut out: write the secret through them, fill the rest with innocent prose, and the recipient reads it through an identical grille — a steganographic skeleton still in use into WWII.', game: 'spotdiff', chapters: ['bacon'] },
      { cat: 'classical', term: 'Beaufort Cipher', zh: '博福特密码', zhDef: '维吉尼亚的镜像变体：密钥字母减明文字母得到密文（c = k − p mod 26）。其自倒置形式被美国 M-209 拉杆式密码机采用为核心运算。', enDef: 'A mirrored Vigenère variant: ciphertext equals key minus plaintext (c = k − p mod 26). Its reciprocal form was adopted as the core operation of the American M-209 lug-based cipher machine.', game: 'vigenere', chapters: ['ww1'] },
      { cat: 'modern', term: 'Password Manager', zh: '口令管理器', zhDef: '用一个强主口令加密保管所有站点随机口令的工具（如 KeePassXC/Bitwarden）。它把「记住 N 个口令」降为「记住 1 个」，让每站唯一长随机口令成为现实。', enDef: 'A tool that stores every site\'s unique random password under one strong master secret (KeePassXC, Bitwarden...). It turns "remember N passwords" into "remember one," making per-site long random secrets practical.', game: 'password-vault', chapters: ['modern'] },
      { cat: 'protocol', term: 'TOTP', zh: '时间型一次性密码', zhDef: 'RFC 6238 标准的双因素验证码：截断(HMAC(共享密钥, 当前时间÷30)) 取六位。30 秒轮换使偷窥到的验证码迅速失效。', enDef: 'The RFC 6238 two-factor code: truncate(HMAC(secret, now ÷ 30)) to six digits. Rotating every 30 seconds, a peeked code dies almost immediately.', game: 'totp-verify', chapters: ['modern'] },
      { cat: 'protocol', term: 'Passkey (FIDO2/WebAuthn)', zh: '通行密钥（Passkey）', zhDef: '基于公私钥对的免密登录标准：私钥留在设备内、签名绑定真实域名——钓鱼站拿不到可用凭据，也没有可泄露的共享秘密。正全面替代 TOTP 与短信验证。', enDef: 'The passwordless login standard built on key pairs: the private key never leaves your device and signatures are bound to the true origin — phishers get nothing, and no shared secret can leak. Now displacing TOTP and SMS codes.', game: 'totp-verify', chapters: ['modern'] },
      { cat: 'protocol', term: 'S/MIME', zh: '安全邮件标准 S/MIME', zhDef: '基于 X.509 证书的邮件加密与签名标准——PGP 的「机构化」对照面：信任由 CA 层级背书而非人际信任网。企业邮件加密的事实标准。', enDef: 'Certificate-based email encryption and signing — PGP\'s institutional mirror: trust flows from CA hierarchies rather than webs of personal endorsements. The corporate standard for sealed mail.', game: 'pgp-mail', chapters: ['modern'] },
      { cat: 'theoretical', term: 'Merkle–Damgård Construction', zh: '梅克尔–达姆加德结构', zhDef: 'MD5/SHA-1/SHA-256 共用的迭代哈希骨架：消息分块逐个压缩进内部状态。正因其结构，长度扩展攻击才成为可能——HMAC 的前缀处理正是为了封堵它。', enDef: 'The iterative hash skeleton shared by MD5, SHA-1 and SHA-256: message blocks compressed into a running state. Its very structure enables length-extension attacks — which HMAC\'s keyed prefix exists to neutralize.', game: 'hashlab', chapters: ['modern'] },
      { cat: 'theoretical', term: 'Blind Signature', zh: '盲签名', zhDef: 'David Chaum 发明的签名形态：签署者看不到文件内容却能为其背书（先「盲化」再签、后去盲）。电子现金与匿名投票协议的核心组件。', enDef: 'David Chaum\'s scheme where the signer endorses a message without seeing it (blind first, unblind after) — the core of e-cash and anonymous voting protocols.', game: 'blind-sign', chapters: ['modern'] },
      { cat: 'protocol', term: 'PAKE', zh: '口令认证密钥交换（PAKE）', zhDef: '在仅共享弱口令的两端协商出强会话密钥，且窃听者无法离线暴力验证猜测（如 SRP、OPAQUE）。Wi-Fi WPA3 的握手核心正是 PAKE。', enDef: 'Protocols (SRP, OPAQUE) that turn a shared weak password into a strong session key while denying eavesdroppers offline verification of guesses — the heart of WPA3\'s SAE handshake.', game: 'password-vault', chapters: ['modern'] },
      { cat: 'protocol', term: 'Noise Protocol Framework', zh: 'Noise 协议框架', zhDef: '一组精挑的握手模式组合框架（XX/IK/pskN……），Signal、WhatsApp、WireGuard 均采用其变体——用最短的规范描述现代安全信道如何建立。', enDef: 'A framework of hand-picked handshake patterns (XX, IK, pskN...) adopted in variant form by Signal, WhatsApp and WireGuard — modern secure channels described in the fewest possible words.', game: 'bb84', chapters: ['modern'] },
      { cat: 'classical', term: 'Tabula Recta', zh: '维吉尼亚方表', zhDef: '26×26 字母方阵：第 i 行是字母表左移 i 位的结果。维吉尼亚/博福特等所有多表替换的查表核心——一张表统治古典密码两百年。', enDef: 'A 26×26 letter square whose row i is the alphabet shifted by i. The lookup heart of Vigenere, Beaufort and every polyalphabetic classical cipher.', game: 'vigenere', chapters: ['bacon'] },
      { cat: 'classical', term: 'Nomenclator', zh: '名词码簿', zhDef: '文艺复兴欧洲外交的主流体制：常用音节/人名/地名配码 + 其余字母简单替换的混合密码本。罗斯林伯爵因破译它声名鹊起。', enDef: 'Renaissance Europe\'s diplomatic workhorse: a codebook of syllables, names and places layered over simple substitution. Frequency analysis alone could not touch it — until codebook reconstruction did.', game: 'nihilist', chapters: ['bacon'] },
      { cat: 'classical', term: 'Great Cipher of Louis XIV', zh: '路易十四大密码', zhDef: '罗西尼奥尔父子为法王设计的数字码本：587 个码元代表音节而非字母，且无规律跳变——两百年无人能破，直到巴泽里用「猜音节」战术攻破王室秘密。', enDef: 'The Rossignols\' numeric code for Louis XIV: 587 groups standing for syllables, not letters, with irregular jumps. Unbroken for two centuries until Bazeries attacked it syllable by syllable.', game: 'detective', chapters: ['ww1'] },
      { cat: 'protocol', term: 'WireGuard', zh: 'WireGuard', zhDef: '2015 年出现的现代 VPN 协议：仅约 4000 行代码，固定使用 Curve25519+ChaCha20-Poly1305+BLAKE2s 的 Noise 握手变体——以极简面缩小攻击面。', enDef: 'A modern VPN protocol (2015): ~4,000 lines of code with a fixed Noise-based handshake over Curve25519, ChaCha20-Poly1305 and BLAKE2s — minimalism as an attack-surface strategy.', game: 'bb84', chapters: ['modern'] },
      { cat: 'protocol', term: 'Threshold Signature', zh: '门限签名', zhDef: '(t,n) 门限思想的签名版：任意 t 方合作才能产出一个有效签名，签名本身不暴露参与人数与份额。机构托管钱包与多方审批的基础设施。', enDef: 'Signatures under (t,n) secret sharing: any t parties jointly produce one valid signature that reveals nothing about the shares or participants — the backbone of institutional custody and multi-party approval.', game: 'shamir', chapters: ['modern'] },
      { cat: 'methods', term: 'S-Box', zh: 'S 盒（替换盒）', zhDef: '分组密码的非线性核心部件：m 位进 n 位出的查表替换。AES 的 8→8 S 盒由乘法逆元加仿射变换构成，是整个算法唯一的非线性来源。', enDef: 'The nonlinear heart of block ciphers: an m-bit to n-bit substitution table. AES\'s 8-bit S-box combines multiplicative inverses with an affine map — the algorithm\'s only source of nonlinearity.', game: 'aes-lab', chapters: ['modern'] },
      { cat: 'modern', term: 'Key Schedule', zh: '密钥扩展算法', zhDef: '从主密钥派生各轮轮密钥的过程（如 AES 的 RotWord/SubWord/Rcon）。设计目标：主密钥任一比特变化影响所有轮钥、且无法从单个轮钥反推主密钥。', enDef: 'The routine deriving per-round keys from the master key (AES uses RotWord/SubWord/Rcon). A good schedule makes every master bit influence all round keys and prevents reversing them.', game: 'aes-lab', chapters: ['modern'] },
      { cat: 'modern', term: 'Hashcash', zh: 'Hashcash', zhDef: 'Adam Back 1997 年的反垃圾方案：发件人须为每封邮件付出少量哈希算力。它是工作量证明的直接祖先，比特币白皮书的第一条引用。', enDef: 'Adam Back\'s 1997 anti-spam scheme making senders burn a little hash power per mail — the direct ancestor of proof-of-work and the first citation in Bitcoin\'s whitepaper.', game: 'blockchain-miner', chapters: ['modern'] },
      { cat: 'protocol', term: 'Off-the-Record (OTR)', zh: '离线记录协议（OTR）', zhDef: '2004 年的即时通讯加密协议：端到端加密 + 前向保密 + 可否认性（消息可事后被任何一方伪造，故不构成法律证据）。Signal 双棘轮的前身。', enDef: 'A 2004 IM protocol: end-to-end encryption with forward secrecy and deniability — either party could have forged any past message, so transcripts prove nothing. The ancestor of Signal\'s Double Ratchet.', game: 'pgp-mail', chapters: ['modern'] },
      { cat: 'methods', term: 'Key Derivation for Storage', zh: '存储口令拉伸', zhDef: '把人类口令加工成可安全用作密钥的字节的工序总称：加盐慢哈希（bcrypt/scrypt/Argon2）通过提高每次猜测的成本对抗离线爆破。', enDef: 'Turning human passwords into key-grade bytes: salted slow hashing (bcrypt, scrypt, Argon2) prices each offline guess upward so bulk cracking becomes uneconomical.', game: 'password-vault', chapters: ['modern'] },
      { cat: 'theoretical', term: 'Simulation Paradigm', zh: '模拟范式', zhDef: '零知识证明的现代定义方法：若存在一个不掌握秘密也能产出与真实交互不可区分记录的「模拟器」，则交互不泄露信息。Goldwasser-Micali 图灵奖工作的核心。', enDef: 'The modern definition of zero-knowledge: if a simulator without the secret can produce transcripts indistinguishable from real ones, the interaction leaks nothing — the core of Goldwasser and Micali\'s Turing Award work.', game: 'zkp-cave', chapters: ['quantum'] },

      { cat: 'classical', term: 'Autokey Cipher', zh: '自动密钥加密', zhDef: '维吉尼亚的一个变体：第一个密钥由种子组成，之后每个密文字符自动成为下一个明文字符的密钥——密钥随长度自足，周期消失，频率分析更难。1557 年贝拉索与 19 世纪用改过的形式写下。', enDef: 'A Vigenere self-stretching variant: a short seed starts the key, then every ciphertext character becomes the key for the next plaintext character — no repeating period left to attack. Known to Bellaso in 1557 and re-formed in the 19th century.', game: 'autokey', chapters: ['bacon'] },
      { cat: 'classical', term: 'Homophonic Substitution', zh: '同音替换', zhDef: '给高频字母分配多个替身符号，让相同明文字母出现不同密文字形——字母频率被摊平，单表频率分析对它失效。文艺复兴的密码学家用数字上万种同音码实现它。', enDef: 'High-frequency letters get many aliases so a plaintext letter maps to different ciphertext shapes — frequency histograms flatten and ordinary substitution analysis fails. Renaissance nomenclators implemented it with hundreds of homophones.', game: 'substitution', chapters: ['arab'] },
      { cat: 'classical', term: 'Book Cipher', zh: '书籍密码', zhDef: '用一本共享的书作密钥：密文是页码/行号-字号的坐标列表。没有书就完全解不开——史上最著名的是贝灵诺维尔密码（Beale Ciphers）以《独立宣言》为书，第二份密电破出藏宝地点、另两份至今未解；二战英国 SOE 让特工抄一首诗的字母作一次性密钥（诗码），用完即焚。', enDef: 'A shared book is the key: ciphertext lists page/line-word coordinates. Without the book nothing decrypts — the famous Beale Ciphers used the Declaration of Independence as their book (paper #2 solved, #1/#3 still open); in WWII Britain\'s SOE gave agents poem codes, one-time keys burnt after use.', game: 'book-cipher', chapters: ['arab'] },
      { cat: 'classical', term: 'Null Cipher', zh: '空密码（归零密码）', zhDef: '把真假字母混在同一条消息里，只按约定位置抽取真字母。小写、偶数字母、每板第 3 字都是常见约定——与格栅一样属于「藏而不掩」。', enDef: 'Real letters hide inside an innocent message, extracted by position (e.g. lowercase letters, even positions). Like grilles, it hides existence rather than content.', game: 'bacon', chapters: ['bacon'] },
      { cat: 'classical', term: 'Porta Cipher', zh: '波尔塔密码', zhDef: '波尔塔 1563 年发明的自互逆的多表密码：密钥字母一一对应整个字对，加密和解密是同一张表。它是文艺复兴意大利学派最有生命力的设计之一，被收录进 19 世纪的职业密码教材并延用至一战。', enDef: 'Porta\'s 1563 self-reciprocal polyalphabetic cipher: each key letter covers an entire pair of alphabets, and the same table both encrypts and decrypts — one of the Renaissance Italian school\'s most durable designs, still in WWII textbooks.', game: 'vigenere', chapters: ['bacon'] },
      { cat: 'classical', term: 'Typex', zh: '迪普克斯', zhDef: '英国 1934 年起以商用 Enigma 为基础自行改造的转子密码机：五只转子（两只固定、三只随键步进）+ 反射器 + 打字机直印明文/密文纸条，1937 年首批交付 RAF，Typex Mk II 打满二战；德军密码学家始终未能破译 Typex 通信。', enDef: 'The British adaptation of the commercial Enigma, designed from 1934: five rotors (two static, three stepping), a reflector and a typewriter printing plaintext/ciphertext strips. The first Mk I batch reached the RAF in 1937 and the Mk II served through WWII — German codebreakers never read Typex traffic.', game: 'typex', chapters: ['bletchley'] },
      { cat: 'classical', term: 'Hagelin C-38', zh: '哈格林 C-38', zhDef: '瑞典工程师鲍里斯·哈格林 1930 年代设计的拉杆型机械密码机，美国以 M-209 之名装备全军 14 万台；其核心运算是博福特式自倒置，二战中起了巨大而低调的作用。', enDef: 'Boris Hagelin\'s 1930s lug-based cipher machine, produced for the US as M-209 and fielded in 140,000 units. Its heart is a Beaufort-style self-inverse operation — the workhorse of WWII field cryptography.', game: 'm209', chapters: ['ww1'] },
      { cat: 'modern', term: 'SHA-2', zh: 'SHA-256 家族', zhDef: 'NIST 2001 年（标准 FIPS 180-4）修订的标准哈希家族，包含 SHA-224/256/384/512，至今仍是互联网默认哈希。它以 Merkle-Damgård 结构建造，输出的 256 位是其最常用成员。', enDef: 'The NIST family standardized as FIPS 180-4: SHA-224/256/384/512, the internet\'s default hashes. Built on Merkle-Damgård chaining, its 256-bit member secures nearly everything.', game: 'hashlab', chapters: ['modern'] },
      { cat: 'theoretical', term: 'Sponge Construction', zh: '海绵结构', zhDef: '把哈希做成「吸收-挤压」两阶段：数据块被吸收进内部状态，再择取任意长度输出。Keccak（SHA-3）一举取代 Merkle-Damgård 并免疫长度扩展。', enDef: 'Hash-pipeline arranged as absorb-squeeze: message blocks dissolve into a state, then a stream is squeezed out at any length. Keccak (SHA-3) made sponge construction the successor to Merkle-Damgård, immune to length extension.', game: 'hashlab', chapters: ['modern'] },
      { cat: 'protocol', term: 'Diffie-Hellman Key Exchange', zh: '迪菲-赫尔曼密钥交换', zhDef: '1976 年 Whitfield Diffie 与 Martin Hellman 公钥革命的核心：双方不经秘密信道，各自用数学交换公开值，最终得到相同的私密字串。它的安全性基于离散对数难题。', enDef: 'The centerpiece of Diffie and Hellman\'s 1976 public-key revolution: two strangers exchange public values over any channel and end up with the same secret. Security rests on the discrete-log assumption.', game: 'dh-handshake', chapters: ['modern'] },
      { cat: 'modern', term: 'NTRU', zh: 'NTRU', zhDef: '1996 年公布、2010 年进入 IEEE 标准的格基公钥体制：用多项式环上的小系数交换完成密钥协商，加解密极快且据信抗量子。', enDef: 'A lattice public-key system first published in 1996 and standardized in IEEE 1363: keys exchange over polynomial rings with small coefficients, fast, and believed quantum-resistant.', game: 'pqc-match', chapters: ['modern'] },
      { cat: 'modern', term: 'Paillier Encryption', zh: 'Paillier 门限加密', zhDef: '1999 年 Pascal Paillier 提出的基于复合数残差的加法同态体制：密文乘法对应明文加法——它让加密的总值可被统计而不泄露单项。银行、隐私计票与多方计算都用它。', enDef: 'Pascal Paillier\'s 1999 additively-homomorphic scheme on composite residues: ciphertext multiplication equals plaintext addition, so totals can be computed without revealing items — used in banking, privacy voting and multiparty computation.', game: 'homomorphic-lab', chapters: ['modern'] },
      { cat: 'modern', term: 'Rabin Cryptosystem', zh: '拉宾加密', zhDef: '1979 年 Michael Rabin 提出的第一个可公开证明「破译等价于因数分解」的体制：加密是模平方，解密求平方根。虽有一义多解，但那也正是它的证明亮点。', enDef: 'Michael Rabin\'s 1979 scheme, the first to publicly prove breaking it equals factoring: encryption is modular squaring, decryption finds square roots. Its ambiguity is precisely what makes the proof work.', game: 'rsa', chapters: ['modern'] },
      { cat: 'protocol', term: 'PGP (Pretty Good Privacy)', zh: 'PGP 加密邮件', zhDef: '1991 年 Phil Zimmermann 向全球发放的第一个个人级加密邮件系统：混合加密 + 数字签名 + 信任之网。今天的企业标准 S/MIME 与个人安全邮件仍以它为原形。', enDef: 'The first personal-grade encrypted email system, released by Phil Zimmermann in 1991: hybrid encryption plus signatures plus the Web of Trust. Corporate S/MIME and personal secure mail still follow its blueprint.', game: 'pgp-mail', chapters: ['modern'] },
      { cat: 'protocol', term: 'SSH', zh: 'SSH 安全外壳', zhDef: '1995 年 Tatu Ylönen 在芬兰设计的远程登录协议：用公钥挑战-响应代替口令，Diffie-Hellman 会话密钥经公钥认证后建立。从 PuTTY 到服务器运维，每天数十亿次 SSH 连接。', enDef: 'Tatu Ylönen\'s 1995 remote-login protocol: public-key challenge-response replaces passwords, then a DH session key flows under public-key authentication. Servers, pipelines and git — billions of SSH sessions a day.', game: 'rsa', chapters: ['modern'] },
      { cat: 'protocol', term: 'Tor', zh: '洋葱路由', zhDef: '匿名浏览网络：流量由三层节点（入口/中间/出口）层层洋葱式加密，每个节点只见下一跳，链路永不完整——从身份泄露到规避审查，它是公认的匿名学标杆。', enDef: 'The anonymity network that encrypts traffic in three layers through entry, middle and exit nodes: each node sees only its hop, so no one holds the whole route — the gold standard for anti-censorship anonymity.', game: 'tor-onion', chapters: ['modern'] },
      { cat: 'methods', term: 'Cold Boot', zh: '冷启动攻击', zhDef: '利用 DRAM「断电后仍保留数据数秒」的物理缺陷：冰冷或重插刷掉密钥后，用差分扫描导出内存中的 AES 密钥。2008 年 Princeton 团队证明甚至能从笔记本内存里恢复加密盘密钥。', enDef: 'DRAM retains data for seconds after power-off: freeze or reinsert it, then dump the memory and extract AES keys. Princeton\'s 2008 team recovered disk-encryption keys out of laptops this way.', game: 'enigma', chapters: ['modern'] },
      { cat: 'modern', term: 'Stream Cipher (Keystream)', zh: '流密码（密钥流）', zhDef: '用一小段密钥流与明文逐位异或，像 OTP 但用确定性 PRNG 生成密钥流——RC4、A5/1、ChaCha20 都属此类。它们快、轻便，但常见事故的元凶（nonce 复用）。', enDef: 'XOR plaintext bit by bit with a pseudorandom keystream — deterministic OTP without key distribution. RC4, A5/1 and ChaCha20 are members, and nonce reuse is the classic disaster.', game: 'xor', chapters: ['modern'] },
      { cat: 'protocol', term: 'A5/1', zh: 'A5/1 GSM 密码', zhDef: '由 3 个短 LFSR 组成的 GSM 手机密码，用来加密通话与短信。GSM 有背门与无背门两说——实战上它弱到 2009 年 Nohl 用彩虹表数分钟破掉，各大安全会议指责它「22 年不升级」。', enDef: 'The GSM cipher of three short LFSRs, protecting calls and texts. It is so weak that Nohl\'s 2009 rainbow-table attack broke it in minutes before a live conference audience — and GSM kept it for years.', game: 'morse', chapters: ['modern'] },
      { cat: 'theoretical', term: 'Multiparty Computation (MPC)', zh: '多方计算', zhDef: '让多人在不暴露私密输入的前提下共同计算一个函数。经典问题「百万富翁问题」：两位百万富翁如何比谁更富而不露出数字？——答案就是 MPC 的雏形，雅奥氏协议后来成为理论基石。', enDef: 'Several parties compute a function without revealing their private inputs. The classic Millionaire\'s Problem — compare fortunes without revealing them — generated the protocols that became MPC\'s foundation.', game: 'shamir', chapters: ['modern'] },
      { cat: 'theoretical', term: 'Zero-Knowledge Sudoku', zh: '零知识数独', zhDef: '用零知识证明展示「这个数独有解」而又不透露任何一个格子的值：把上色后的解与格纸叠加，挑战一列、一行或一宫，让验证者只看到解法排列而看不到解法本身。这是 ZKP 最优雅的科普演示，我们的洞穴与数独都用了它。', enDef: 'A favorite demo of zero-knowledge: prove a sudoku puzzle has a solution without leaking any cell. Every challenge — row, column or box — reveals ordering without revealing the solution.', game: 'zkp-cave', chapters: ['quantum'] },
      { cat: 'protocol', term: 'Key Encapsulation Mechanism', zh: '密钥封装 KEM', zhDef: '一种把「公钥加密」重新表述为标准化的密钥容器：输出一对（会话密钥, 封装密文）。TLS 1.3 用 KEM 交换数据，NIST 后量子标准以 ML-KEM 为主将。', enDef: 'A formal way of describing public-key encryption: outputs a pair (session key, encapsulated ciphertext). TLS 1.3 uses KEMs for key transmission, and NIST\'s post-quantum flagship is ML-KEM.', game: 'pqc-match', chapters: ['modern'] },
      { cat: 'protocol', term: 'SM9', zh: '国密 SM9', zhDef: '基于双线性对的标识密码标准：公钥不需要证书，用使用者标识（如手机号、邮箱）即可验证签名——国密「用身份就当钥匙」的技术路线，与 SM2 短密钥、SM3 哈希、SM4 加密并称国密四件套。', enDef: 'The Chinese national identity-based standard built on bilinear pairs: the public key comes from the user\'s identifier (phone, email) instead of certificates — the 4th piece of China\'s SM family with SM2, SM3 and SM4.', game: 'gm-gateway', chapters: ['modern'] },
      { cat: 'protocol', term: 'Two-Factor Authentication', zh: '双因素认证（2FA）', zhDef: '把「你知道的」「你拥有的」「你是什么」三种独立维度取两种做组合验证——仅口令泄露不足以过关。短信验证、TOTP、Passkey、硬件密钥依次是它的实现演进。', enDef: 'Verifying with two-independent of the three classes: something you know, have or are. Password-plus-SMS, TOTP, then Passkeys and security keys are the species of this umbrella.', game: 'totp-verify', chapters: ['modern'] },
      { cat: 'classical', term: 'Homophonic with Nomenclator', zh: '含名词名表的同音密码', zhDef: '把「高频字母多替身+人地官名专属码元」两种手段叠在一起的文艺复兴高级体制——即使是频率分析高手也无法只凭统计穿透其第 2 层。', enDef: 'The Renaissance high-grade system that stacks homophones plus dedicated codewords for people, places and offices — beyond the reach of bare frequency analysis.', game: 'nihilist', chapters: ['bacon'] },
      { cat: 'modern', term: 'Post-Quantum Hybrids', zh: '后量子混合方案', zhDef: '在 NIST 标准未完全稳妥时，把经典与后量子算法叠加的迁移策略：TLS 1.3 用 X25519 + ML-KEM 或其他混合密钥交换组，任一侧被破防，整体仍安全。', enDef: 'The migration strategy of stacking classical and post-quantum algorithms while standards mature: TLS 1.3 carries hybrid groups like X25519+ML-KEM so breaking either side still leaves the session safe.', game: 'pqc-match', chapters: ['quantum'] },
      { cat: 'methods', term: 'Differential Side-Channel', zh: '差分侧信道（DPA）', zhDef: '对数千条采样功率曲线做统计相关分析，把密钥逐位从设备中抠出来——不是破解算法，而是破解硬件。Kocher 2001 年发明，是智能卡芯片安全的头号劲敌。', enDef: 'Correlating thousands of power traces to descale the key bit by bit — attacking the hardware, not the crypto. Kocher established it in 2001; it remains the biggest threat to embedded chips.', game: 'side-channel-lab', chapters: ['modern'] },
      { cat: 'modern', term: 'Feistel vs SPN (Confusion vs Diffusion)', zh: '混淆 vs 扩散', zhDef: '混淆：让密钥与明文字面关系复杂化（S 盒）；扩散：让每个明文字节影响整个输出（位移与列混合）。香农定义的这两个变化量是一切成块密码的结构宪法——AES 的每轮都是它们的精刻。', enDef: 'Confusion makes key-to-ciphertext relations opaque (S-boxes); diffusion spreads every plaintext bit across the whole block (shifts and mixing). Shannon\'s two properties are the constitution of every block cipher.', game: 'sm4', chapters: ['modern'] },
      { cat: 'methods', term: 'Kasiski vs Index of Coincidence', zh: '卡西斯基检验与重合指数', zhDef: '破译多表密码的两把钥匙：卡西斯基（重复模式间距 = 密钥周期倍数的众数）与重合指数（频率统计越接近英文，周期越可能正确）。普拉特 1863 年公布，成为 19 世纪多表分析的第一定理。', enDef: 'Breaking polyalphabetic ciphers: Kasiski\'s repeated-group distances reveal the period, and the index of coincidence ranks which period is right. First published in 1863, it opened the 19th century\'s systematic attack.', game: 'vigenere', chapters: ['arab'] },
      { cat: 'methods', term: 'Banburismus', zh: '班伯里斯穆斯统计破译法', zhDef: '布莱切利园 1941 年前后用于海战 Enigma 的统计破译术：用「深度」电文对的多重字母重合率给可能的轮序打分、逐级排除，由 A. 图灵主导推广——Bombe 之外的第二台「统计机器」。', enDef: 'The statistical sieve used at Bletchley Park from 1941 on naval Enigma: score possible rotor orders by the multiple coincidences of depth pairs, then eliminate. Driven by Alan Turing — codebreaking\'s second engine beside the Bombe.', game: 'bombe', chapters: ['bletchley'] },
      { cat: 'methods', term: 'Depth', zh: '深度（密钥复用深度）', zhDef: '同一密钥材料对多封消息的重复使用——JN-25 同版加表期内多封电文相减抵消加表，破译员从「深度对」反推明文；VENONA 的 OTP 复用是同一种深度的重演。', enDef: 'The reuse of the same key material across many messages: within one JN-25 additive period, subtracting messages cancels the table and reveals plaintext differences; VENONA\'s OTP reuse was the same depth all over again.', game: 'jn25', chapters: ['midway'] },
      { cat: 'classical', term: 'Codebook', zh: '码本（编码簿）', zhDef: '词句→码组对照簿（如 JN-25 的 5 位数字码）：与逐字母变换的密码（cipher）相对，「码本 + 每日加表」的双层结构是二战海军密码的标准配置。', enDef: 'A word-to-codegroup book (e.g. JN-25\'s five-digit groups): as opposed to letter-by-letter ciphers, the codebook-plus-daily-additive double layer was the standard of WWII naval codes.', game: 'jn25', chapters: ['midway', 'venona'] },
      { cat: 'protocol', term: 'Content Security Policy (CSP)', zh: '内容安全策略（CSP）', zhDef: '浏览器强制执行的加载白名单：只允许可信来源的脚本/样式，内联与注入默认拒绝——即使 XSS 防护被绕过，也无法执行攻击者代码。', enDef: 'A browser-enforced allowlist for scripts and styles: inline and injected code are refused by default — even if an XSS filter is bypassed, attacker code cannot run.', game: 'phishhunt', chapters: ['modern'] },
      { cat: 'methods', term: 'Fault Attack', zh: '故障注入攻击', zhDef: '用电压毛刺/时钟脉冲/激光把运算打出错，再对比错误输出反推秘密——无校验的 CRT-RSA 实现是经典靶点（1996 Bellcore 论文），也是「实现安全」与「算法安全」的分界线。', enDef: 'Glitch the computation with voltage spikes, clock pulses or lasers, then compare faulty outputs to recover secrets — the unvalidated CRT-RSA implementation is the classic target (Bellcore 1996), the dividing line between implementation and algorithm security.', game: 'side-channel-lab', chapters: ['modern'] },
      { cat: 'methods', term: 'Replay Attack', zh: '重放攻击', zhDef: '把截获的合法消息原样重发以骗取认证或支付——TOTP 的时间片、nonce 计数器与挑战-响应协议都在对抗重放：旧凭证不因合法而可以再用。', enDef: 'Resending a captured, legitimate message to cheat authentication or payment — TOTP time slices, nonce counters and challenge-response all fight replay: being genuine does not make it spendable twice.', game: 'totp-verify', chapters: ['modern'] },
      { cat: 'modern', term: 'Padding', zh: '填充（Padding）', zhDef: '把明文对齐到分组大小的填充字节；CBC 对填充错误的区别反应可构成填充预言攻击（Bleichenbacher），因此 AEAD 时代普遍改用无需填充的 CTR/GCM 路线。', enDef: 'Bytes aligning plaintext to a block size; CBC\'s distinct reactions to padding errors enable the padding-oracle attack (Bleichenbacher), which is why the AEAD era moved to padding-free CTR/GCM.', game: 'aes-lab', chapters: ['modern'] },
      { cat: 'postquantum', term: 'SLH-DSA (SPHINCS+)', zh: 'SLH-DSA（SPHINCS+）', zhDef: 'NIST FIPS 205 的标准哈希签名：安全性只建立在哈希函数的假设上，无状态、不需要格/编码——签名约 17KB、较慢，是最保守的后量子选择。', enDef: 'NIST\'s FIPS 205 hash-based signature: security rests on hash assumptions alone, stateless, no lattices — signatures near 17KB and slow, the most conservative post-quantum pick.', game: 'pqc-match', chapters: ['quantum'] },
      { cat: 'protocol', term: 'Identity-Based Encryption (IBE)', zh: '标识加密（IBE）', zhDef: '标识即公钥：用邮箱/手机号等直接当公钥，私钥由受信的私钥生成中心（PKG）按标识签发——证书链整个省掉；国密 SM9 即此路线。', enDef: 'Identifier-as-public-key: your email or phone number IS the public key, and a trusted private-key generator issues the matching private key — the certificate hierarchy vanishes; China\'s SM9 follows this route.', game: 'rsa', chapters: ['modern'] },
      { cat: 'methods', term: 'SIGINT', zh: '信号情报（SIGINT）', zhDef: '截收无线电/雷达/通信并从中提炼情报的完整链条——破译只是其中一环，流量分析与测向同为核心；VENONA、中途岛等都是 SIGINT 的经典战例。', enDef: 'The full chain of intercepting radio, radar and communications for intelligence — codebreaking is one link; traffic analysis and direction finding are equally core. VENONA and Midway are classic SIGINT campaigns.', game: 'venona', chapters: ['venona'] },
      { cat: 'protocol', term: 'Zero Trust Architecture', zh: '零信任架构', zhDef: '「永不信任、永远验证」的访问模型：网络分段 + 逐请求鉴权 + 最小权限，替代「内网即安全」的边界思维——每个请求都重新核验身份与设备。', enDef: 'Never trust, always verify: segmentation, per-request authentication and least privilege replace the "inside the firewall is safe" mindset — every request re-validates identity and device.', game: 'password-vault', chapters: ['modern'] },
      { cat: 'protocol', term: 'Ransomware', zh: '勒索软件', zhDef: '加密受害者文件并索取赎金的恶意软件：钓鱼附件与漏洞渗透是主要入口；隔离备份、及时补丁、不向勒索低头是通行的应对策略。', enDef: 'Malware that encrypts files and demands ransom: phishing attachments and exploit breaches are the main entry points; isolated backups, patching and refusing to pay are the standard playbook.', game: 'phishhunt', chapters: ['modern'] },
      { cat: 'protocol', term: 'CAPTCHA', zh: '人机验证（CAPTCHA）', zhDef: '区分人与机器的挑战（扭曲字母、图片选择）：对抗垃圾注册与暴力枚举，也在被打码平台与 AI 破解——如今向无感行为验证演进。', enDef: 'Challenges telling humans from bots (distorted letters, image selection): they fight spam registration and brute-force enumeration, yet face crowdsourcing and AI — evolving toward invisible behavioral checks.', game: 'phishhunt', chapters: ['modern'] },
      { cat: 'classical', term: 'Navajo Code Talkers', zh: '纳瓦霍语密码通话员', zhDef: '二战美军以纳瓦霍语为基底的「语言密码」：无文字、语法极复杂的语言自带壁垒，再叠 400 条军用词汇码（坦克=乌龟、潜艇=铁鱼）——日军截收到终战未能破译；1968 解密，2001 年 Original 29 获国会金质奖章。', enDef: 'The WWII US military\'s language cipher: an unwritten, grammatically forbidding native language as the barrier, stacked with ~400 military codewords (tank=turtle, submarine=iron fish). Japan never broke it; declassified 1968, the Original 29 received Congressional Gold Medals in 2001.', game: 'navajo-talker', chapters: ['midway'] },
      { cat: 'classical', term: 'Rockex Cipher', zh: '罗克斯密码机', zhDef: '英国战后主力滚轮密码机（源自 Bletchley 的 Lorenz 研究，1943 年设计、战后列装）：转子加打印机直出密文，服务英国外交与英联邦电报直到 1960 年代。', enDef: 'The UK\'s postwar workhorse rotor machine (built from Bletchley\'s Lorenz research, designed 1943, fielded after the war): rotors plus a printer, carrying British diplomatic traffic into the 1960s.', chapters: ['lorenz'] },
      { cat: 'classical', term: 'Combined Cipher Machine (CCM)', zh: '联合密码机（CCM）', zhDef: '二战后期英美互换加密电报的共电机：把英国 Typex 与美国 Mark 22 改装为同一加密体系，盟军跨大西洋通信第一次共同安全。', enDef: 'The Anglo-American interoperable machine of late WWII: British Typex and US Mark 22 adapted to one cipher, giving Allied Atlantic traffic a single shared security.', chapters: ['lorenz'] },
      { cat: 'classical', term: 'Double Transposition', zh: '双重换位密码', zhDef: '同一明文做两次密钥列换位（第二次用不同密钥写作另一宽度的表格）：字母不变、位置被连续打散——古典密码学里最顽强的换位体系，冷战初期由苏联间谍与荷兰抵抗组织使用。', enDef: 'Two keyed columnar transpositions applied in sequence (second pass with a different key/width): letters unchanged, order scrambled twice — the toughest classical transposition, used by Dutch resistance and early Cold War spies.', chapters: ['ww1'] },
      { cat: 'classical', term: 'Four-Square Cipher', zh: '四格密码', zhDef: 'Playfair 的改良：用四个 5×5 方阵（两个密钥方阵）同格对加密——比 Playfair 更难破，是英国皇家学会 1900 年代推荐的手工双字母密码。', enDef: 'An improved Playfair: four 5x5 squares (two keyed) encrypt digraphs by mirror positions — harder to break, recommended by the RSA in its 1900s manual ciphers.', chapters: ['ww1'] },
      { cat: 'modern', term: 'KASUMI', zh: 'KASUMI（3G 分组密码）', zhDef: '3G 移动通信的标准分组密码（基于 MILENAGE 框架）：64 位分组、128 位密钥、Feistel 结构——WCDMA 网络加密与完整性保护的基础算法。', enDef: 'The 3G standard block cipher (inside the MILENAGE framework): 64-bit blocks, 128-bit keys, Feistel structure — the base of WCDMA confidentiality and integrity.', chapters: ['modern'] },
      { cat: 'modern', term: 'RC6', zh: 'RC6', zhDef: 'Rivest 等人 1998 年提交 AES 竞标的候选算法：数据依赖循环移位让每轮运算与密钥/数据耦合，最终惜败于 Rijndael——但它的设计思想影响了后续分组密码多样性。', enDef: 'Rivest\'s 1998 AES candidate: data-dependent rotations couple each round to the data itself. It lost to Rijndael but its ideas shaped block-cipher diversity.', chapters: ['modern'] },
      { cat: 'modern', term: 'CFB/OFB 模式', zh: 'CFB/OFB 模式', zhDef: '把分组密码变成流密码的两种模式：CFB 用密文反馈加密，OFB 用输出反馈——都能逐比特/逐字节处理且无需填充；代价是错误传播（CFB）与不支持并行（OFB）。', enDef: 'Two modes that turn a block cipher into a stream cipher: ciphertext feedback (CFB) and output feedback (OFB) — bit/byte granular, no padding; trade-offs are error propagation (CFB) and no parallelism (OFB).', game: 'aes-lab', chapters: ['modern'] },
      { cat: 'modern', term: 'RSA Padding (PKCS#1)', zh: 'RSA 填充（PKCS#1）', zhDef: 'RSA 裸加密即噩梦：确定性、可被数学攻击。PKCS#1 v1.5 用结构化的随机填充（v2 用 OAEP）把冗余注入——没有正确填充的 RSA 实现，就是教科书里最经典的漏洞。', enDef: 'Textbook RSA is a nightmare: deterministic and mathematically attackable. PKCS#1 v1.5 adds structured random padding (v2 OAEP) — unpadded/incorrectly padded RSA defines the classic implementation flaw.', game: 'rsa', chapters: ['modern'] },
      { cat: 'methods', term: 'Key Confusion Attack', zh: '密钥混淆攻击', zhDef: '让协议双方对「同一把密钥」做出不同解释的攻击：典型如签名中的哈希截断混淆（Curve25519 指纹欺诈、TLS 早期版本）——现代设计用域分离（DOMAIN 标签）根治。', enDef: 'Making two parties interpret the same key differently — classic cases are hash-truncation confusion in signatures and early TLS; modern designs fix it with domain separation.', chapters: ['modern'] },
      { cat: 'methods', term: 'Algebraic Attack', zh: '代数攻击', zhDef: '把密码写成低次数方程组并用解方程器求解的攻击范式：流密码（非线性反馈）与某些分组密码的弱点由此暴露——设计者必须保证系统「代数次数足够高」。', enDef: 'Model the cipher as low-degree polynomial equations and solve: stream ciphers and some block ciphers fall to it — designers must keep algebraic degree high.', chapters: ['modern'] },
      { cat: 'methods', term: 'Dictionary Attack', zh: '字典攻击', zhDef: '用常见口令词典（+规则变形）逐条试签的破解方式：比纯暴力高效得多——「Salt + 慢哈希 + 口令短语」就是它的终结者。', enDef: 'Testing candidate passwords from common dictionaries plus mutations — far more efficient than brute force. Salt + slow hash + passphrases end it.', game: 'password-vault', chapters: ['modern'] },
      { cat: 'methods', term: 'Speculative Execution Side-Channel', zh: '推测执行侧信道（Spectre/Meltdown）', zhDef: 'CPU 为提速进行「推测执行」并提前访问缓存，其痕迹被时序/缓存信道读出——2017 年的 Spectre/Meltdown 证明：即使代码零漏洞，芯片级的绩效优化也会泄露秘密。', enDef: 'CPUs speculatively execute and probe caches ahead of time; timing/cache side-channels read the residue. The 2017 Spectre/Meltdown class showed that chip-level optimizations leak secrets even with flawless code.', chapters: ['modern'] },
      { cat: 'modern', term: 'DH Parameter Validation', zh: 'DH 参数安全校验', zhDef: 'DH 的安全不只靠大素数：小阶子群攻击（参数未验证时把共享值旋進小群）与素性保证（安全素数）——现代库强制校验 p 素性与 g 阶，是「算法正确≠参数正确」的活例。', enDef: 'DH security is not just about big primes: small-subgroup attacks (unvalidated params trap the shared value) and primality guarantees (safe primes). Modern libraries validate p and the order of g — math alone isn\'t enough.', game: 'dh-handshake', chapters: ['modern'] },
      { cat: 'modern', term: 'NIST P-256 (secp256r1)', zh: 'NIST P-256 曲线', zhDef: '应用最广的椭圆曲线之一：256 位素域、生成参数经 NIST 标准化——TLS 1.3 主流套件与国密 SM2 之外的国际默认曲线；争议在其参数的「无法解释来源」。', enDef: 'The most deployed curve: 256-bit prime field, NIST-standardized parameters — the international default beside SM2 in TLS 1.3 suites; one controversy is the unexplained source of its constants.', chapters: ['modern'] },
      { cat: 'modern', term: 'KMAC / cSHAKE', zh: 'KMAC / cSHAKE 族', zhDef: 'SHA-3 海绵构造的可定制家族：cSHAKE 加上下文与功能名、KMAC 把它升级为密钥 MAC——为密码学提供「域分离」的原生工具。', enDef: 'The customizable SHA-3 sponge family: cSHAKE adds context and function names, KMAC turns it into a keyed MAC — giving domain separation natively.', chapters: ['modern'] },
      { cat: 'protocol', term: 'Secure Boot & Firmware Signing', zh: '安全启动与固件签名', zhDef: '从第一条指令起就用「信任根+签名链」验证：引导装载器验内核、内核验固件、固件验外设——密钥链断了哪一环，攻击者就栽在哪一环。', enDef: 'Verify from the first instruction with a root of trust plus signature chain: bootloader checks kernel, kernel checks firmware, firmware checks peripherals — the chain breaks where an attacker gets in.', chapters: ['modern'] },
      { cat: 'protocol', term: 'FIPS 140', zh: '密码模块标准（FIPS 140）', zhDef: '美国 NIST 的密码模块安全等级标准（FIPS 140-2/140-3）：物理外壳、密钥管理、随机测试、自检四层评测——企业采购与政府合规的通用基准。', enDef: 'NIST\'s security-level standard for cryptographic modules (140-2/140-3): physical envelope, key management, RNG tests, self-tests — the common baseline for procurement and government compliance.', chapters: ['modern'] },
      { cat: 'protocol', term: 'Cryptography Law of China', zh: '《密码法》', zhDef: '中国 2020 年施行的密码领域基础法律：把密码分为核心/普通/商用三类，确立商用密码「市场准入+检测认证」体制，是国密体系法治化的里程碑。', enDef: 'China\'s 2020 foundational cryptography law: three tiers (core, ordinary, commercial) with a market-access and testing regime for the commercial tier — the rule-of-law milestone of the SM ecosystem.', chapters: ['modern'] },
      { cat: 'protocol', term: 'Commercial Cryptography Regulation', zh: '《商用密码管理条例》', zhDef: '2023 年修订的配套行政法规：细化商用密码检测认证、安全评估与进口出口清单，推动 SM 系列算法在电子政务与金融基础设施的全面落地。', enDef: 'The 2023 implementing regulation: certification, security assessment and import/export lists for commercial cryptography — pushing SM algorithms across e-government and financial infrastructure.', chapters: ['modern'] },
      { cat: 'protocol', term: 'HMAC (Keyed Hash MAC)', zh: 'HMAC 消息认证码', zhDef: '用密钥与哈希函数构造的认证码：HMAC(K, M) = H(K ⊕ opad ‖ H(K ⊕ ipad ‖ M))。它只认证不加密（MAC 与加密是两件事：加密保机密，MAC 保真实）；HMAC 属于 MAC 家族（还有基于分组密码 CMAC 等），而内层长度扩展攻击用双填充结构天然免疫——TLS 早期用 HMAC 当握手校验。', enDef: 'A keyed hash MAC: HMAC(K, M) = H(K ⊕ opad ‖ H(K ⊕ ipad ‖ M)). It authenticates without encrypting — confidentiality is encryption’s job, authenticity is the MAC’s. HMAC is one MAC family (besides CMAC built from block ciphers); its nested padding structure shrugs off length-extension attacks, and early TLS used it for handshake verification.', chapters: ['modern'] },
      { cat: 'modern', term: 'RIPEMD & Whirlpool', zh: 'RIPEMD 与 Whirlpool 哈希', zhDef: '两族「非主流但正规」的哈希：RIPEMD 出自 1990 年代欧洲 RIPE 计划（1995，160 位，双管线结构，RIPEMD-160 至今用于 Bitcoin 地址）；Whirlpool 为 2000 年 Rijmen (AES 之父) 与 Barreto 设计的 512 位哈希（基于 AES 精神构造的 8×8 状态盒，入选 ISO/IEC 10118-3）。', enDef: 'Two serious but non-mainstream hash families: RIPEMD from Europe’s RIPE project (1995, 160-bit double-line structure; RIPEMD-160 still secures Bitcoin addresses); Whirlpool, a 512-bit hash by Rijmen (the AES father) and Barreto in 2000, built with an AES-spirited 8×8 state box and listed in ISO/IEC 10118-3.', chapters: ['modern'] },
      { cat: 'theoretical', term: 'ZK Three Properties (Soundness/Completeness/Zero-Knowledge)', zh: '零知识证明三性：完备/可靠性/零知识', zhDef: '完备性（completeness）：命题为真时诚实验证者总接受；可靠性（soundness）：命题为假时任何证明者都难以欺骗接受；零知识（zero knowledge）：验证者除了「命题为真」之外获得不了任何信息——三性齐备才是严格意义的零知识，缺一不可。', enDef: 'Completeness: for a true statement an honest verifier always accepts. Soundness: for a false statement no prover can cheat their way to acceptance. Zero knowledge: the verifier learns nothing beyond the truth of the statement. All three together define rigorous zero-knowledge — missing one breaks it.', chapters: ['modern'] },
      { cat: 'protocol', term: 'DNSSEC', zh: 'DNSSEC 域名安全扩展', zhDef: '给 DNS 加上密码学可信链：区数据用区域密钥签名（RRSIG），子区公钥由父区 DS 记录背书，信任从根锚一路传导；用 NSEC/NSEC3 证明「某名字不存在」。防的主要是「毒化与劫持」——DNS 劫持面前 HTTPS 也会被牵走（证书链可挡，但仍要经过 DNS）。', enDef: 'Cryptographic trust for DNS: zone data is signed (RRSIG), child public keys are endorsed by parent DS records, and trust flows from the root anchor down; NSEC/NSEC3 prove that a name does not exist. Its main enemy is poisoning and hijacking — a DNS answer can even redirect an HTTPS session.', chapters: ['modern'] },
      { cat: 'security', term: 'Supply Chain Attack', zh: '供应链攻击', zhDef: '不直接攻目标，而攻目标的「原料」：篡改上游依赖包、编译器、构建流水线或硬件固件，让被攻者亲手把后门装进自己系统。历史大案：SolarWinds（2020，篡改更新通道）、XZ Utils 后门（2024，投毒开源依赖）、3CX 事件。', enDef: 'Attack the ingredients, not the target: tamper with upstream packages, compilers, build pipelines or firmware so the victim installs the backdoor by themselves. Landmark cases: SolarWinds (2020, poisoned update channel), the XZ Utils backdoor (2024, open-source dependency poisoning), 3CX.', chapters: ['modern'] },
      { cat: 'security', term: 'Zero-Day', zh: '零日漏洞', zhDef: '「零日」指厂商知晓与修补的窗口为零：漏洞被攻击者利用时，厂商还没发现或没补丁——无日志、无特征，防御方只能先假设有鬼。情报界称「令人绝望的对称性」：攻击者只要找到一个 0-day 就能突破一切、且难以探测。', enDef: 'A vulnerability exploited before the vendor knows or patches it — the window is "zero days". No signatures, no logs: defenders must assume the worst. Intelligence services call it the "kill chain" all the way down: one unpatched flaw breaks any stack, invisibly.', chapters: ['modern'] },
      { cat: 'modern', term: 'PRISM & 2013 Surveillance Disclosures', zh: '棱镜计划与 2013 年大规模监控披露', zhDef: '2013 年 6 月，前 NSA 承包商爱德华·斯诺登向媒体披露：美国国家安全局通过 PRISM 程序直接从微软、谷歌、雅虎等九大互联网公司服务器拉取数据，另有「上游」拦截与全球监听——引发全球加密使用大潮（HTTPS 比例从 2013 年的约 30% 升至如今 90%+）。', enDef: 'In June 2013 NSA contractor Edward Snowden revealed mass surveillance: direct access to nine internet giants (PRISM), upstream cable interception and global tapping. The fallout pushed HTTPS from ~30% of web traffic in 2013 to over 90% today.', chapters: ['modern'] },
      { cat: 'security', term: 'CVE & Vulnerability Management', zh: 'CVE 与漏洞管理', zhDef: 'CVE（通用漏洞与暴露）为每个公开漏洞分配唯一编号（如 CVE-2014-0160 = Heartbleed）；配套 CVSS 打分定严重级、CWE 分类、NVD 数据库聚合。漏洞管理 = 资产清单 × 补丁节奏 × 利用情报，核心是把「被公开利用」的风险压到最小。', enDef: 'The Common Vulnerabilities and Exposures registry gives every disclosed flaw a unique ID (CVE-2014-0160 = Heartbleed); CVSS scores severity, CWE classifies root causes, NVD aggregates it all. Vulnerability management = asset inventory × patch cadence × exploitation intelligence.', chapters: ['modern'] },
      { cat: 'theoretical', term: 'Turing Machine (1936)', zh: '图灵机（1936）', zhDef: '图灵在 1936 年《论可计算数》中提出的抽象计算模型：无限纸带 + 读写头 + 状态表，简单到不可思议却等价于任何可计算函数；随即证明停机问题不可判定——「计算机科学之父」由此奠定。程序与数据同存的思想（冯·诺依曼结构的源头）正是密码史上 Colossus 与后来所有计算机的共同血脉。', enDef: 'In 1936 Alan Turing’s "On Computable Numbers" defined an abstract machine: an infinite tape, a head and a state table — astonishingly simple, yet capable of any computable function. He then proved the halting problem undecidable. The notion that programs are data (the von-Neumann lineage) runs from here through Colossus to every computer since.', chapters: ['modern'] },
      { cat: 'modern', term: 'First Computers (ENIAC/EDSAC)', zh: '计算机的诞生（ENIAC/EDSAC）', zhDef: '1943–1945 年宾夕法尼亚大学建成的 ENIAC（电子数字积分计算机）是世界第一台通用电子数字计算机——但它靠插线板重连程序；1949 年剑桥的 EDSAC 第一个实现「存储程序」由内存跑代码，成为现代计算机的真正原型。密码学的机器时代（Colossus 1943、ENIAC 1945）因此与今天的信息安全一脉相承。', enDef: 'ENIAC (1943-45, University of Pennsylvania) was the first general-purpose electronic digital computer — but reprogramming it meant flipping cables; EDSAC (Cambridge, 1949) first ran code from memory, the true blueprint of every modern machine. The machine age of cryptography (Colossus 1943, ENIAC 1945) flows straight into today’s information security.', chapters: ['modern'] },
      { cat: 'classical', term: 'Red Army Radio Cipher', zh: '红军电报密码', zhDef: '20 世纪 30 年代中国工农红军无线电密码：自编密语表 + 手工换码，配合机要译电；破译方面则以曾希圣为代表的无线电侦察队伍从国军惯用重复电文中还原情报，是「自己用密码、同时破对方密码」的双线样本。', enDef: 'Red Army radio ciphers of 1930s China: hand-built code tables plus manual transposition, with a signals-intelligence corps (Zeng Xisheng) reconstructing enemy traffic from habitual repetitions — both encrypting and breaking at once.', chapters: ['modern'] },
      { cat: 'classical', term: 'Half-a-Radio', zh: '半部电台', zhDef: '1930 年底龙冈战斗缴获的国民党军电台：发报机已坏、收报机尚好——红军用它起监听破译的“家”，随后发展出完整无线电侦察体系；毛泽东评价“半部电台起家”是红军情报工作的起点。', enDef: 'A Kuomintang radio captured at Longgang in late 1930 — transmitter smashed, receiver intact — became the Red Army\'s listening and codebreaking "home", growing into a full signals-intelligence system.', chapters: ['modern'] },
];;
